-- 449 dp changes Android UI density; it is not the Roblox viewport size.
local MOBILE_449=UIS.TouchEnabled
local TARGET_MIN_WIDTH_DP=449
-- v6: one-time user-confirmed GREEN placement replaces a blocked recorded spot.
-- Delta readfile/writefile are optional. No fixed green coordinates are invented.
local FIRST_GREEN_FILE="LegacyTTD_TurkeyTown_Redmi449_GreenPoint.json"
local firstGreenVerified=false
local function saveFirstGreen(info)
    if type(writefile)~="function" then
        warn("GREEN POINT SAVE unavailable: Delta writefile missing; copy coordinates from log")
        return false
    end
    local payload={placeId=game.PlaceId,unit="pumpkin_farmer",
        pos=info.pos,ground=info.ground}
    local ok,err=pcall(function() writefile(FIRST_GREEN_FILE,HttpService:JSONEncode(payload)) end)
    if not ok then warn("GREEN POINT SAVE FAILED: "..tostring(err)) end
    return ok
end
local function loadFirstGreen()
    if not MOBILE_449 or type(readfile)~="function" then return end
    local ok,p=pcall(function()return HttpService:JSONDecode(readfile(FIRST_GREEN_FILE))end)
    if not ok or type(p)~="table" or p.placeId~=game.PlaceId or p.unit~="pumpkin_farmer" then return end
    local function valid(a)
        return type(a)=="table" and #a==3 and type(a[1])=="number" and type(a[2])=="number" and type(a[3])=="number"
            and a[1]==a[1] and a[2]==a[2] and a[3]==a[3]
    end
    if not valid(p.pos) or not valid(p.ground) then return end
    local first=data.places and data.places["1"]
    if not first or first.unit~="pumpkin_farmer" then return end
    first.pos=p.pos
    first.ground=p.ground
    firstGreenVerified=true
    print("[Legacy Replay] GREEN POINT LOADED | X="..string.format("%.2f",p.pos[1]).." Z="..string.format("%.2f",p.pos[3]))
end
loadFirstGreen()
-- v7: persist a verified point separately for each first-of-type placement,
-- retaining the existing v6 pumpkin cache for backwards compatibility.
local GREEN_POINTS_FILE="LegacyTTD_TurkeyTown_Redmi449_GreenPoints_v7.json"
local savedGreenPoints={}
if firstGreenVerified then savedGreenPoints[1]=true end
local function validGreenVector(a)
    return type(a)=="table" and #a==3 and type(a[1])=="number"
        and type(a[2])=="number" and type(a[3])=="number"
        and a[1]==a[1] and a[2]==a[2] and a[3]==a[3]
end
local function loadGreenPoints()
    if not MOBILE_449 or type(readfile)~="function" then return end
    local ok,p=pcall(function() return HttpService:JSONDecode(readfile(GREEN_POINTS_FILE)) end)
    if not ok or type(p)~="table" or p.placeId~=game.PlaceId or type(p.points)~="table" then return end
    for id,point in pairs(p.points) do
        local info=data.places[tostring(id)]
        -- Chef #5 is LOCKED to the original motion recording, not last manual spot.
        -- Older v7/v14 cache silently moved him to a different coordinate.
        if info and tonumber(id)~=5 and type(point)=="table" and point.unit==info.unit
            and validGreenVector(point.pos) and validGreenVector(point.ground) then
            info.pos=point.pos
            info.ground=point.ground
            savedGreenPoints[tonumber(id)]=true
            if tonumber(id)==1 then firstGreenVerified=true end
            print(string.format("[Legacy Replay] MOBILE GREEN POINT LOADED #%s | %s | X=%.2f Z=%.2f",
                tostring(id),info.unit,point.pos[1],point.pos[3]))
        end
    end
end
loadGreenPoints()
-- The user confirmed this EXACT first Pumpkin Farmer location by placing it
-- successfully on Redmi 449dp (v6 log: MOBILE GREEN POINT LEARNED #1).
-- Embed only this observed location so a missing/isolated readfile cache does
-- not force manual recalibration every run or repeat blocked original coords.
