if MOBILE_449 and data.places["5"] then
    local chef=data.places["5"]
    print(string.format("[Legacy Replay] CHEF RECORDED LOCK #5 | X=%.5f Y=%.5f Z=%.5f | t=62.50 | cached-green=IGNORED",
        chef.pos[1],chef.pos[2],chef.pos[3]))
end
local function saveGreenPoint(id,info)
    if id==5 then
        -- This placement is prescribed by the recorded route, not calibration.
        return false
    end
    savedGreenPoints[id]=true -- verified in THIS match even if file saving is unavailable
    if id==1 then
        firstGreenVerified=true
        saveFirstGreen(info)
    end
    if type(writefile)~="function" then
        warn("MOBILE GREEN SAVE #"..id.." | Delta has no writefile; copy green coordinates from log")
        return false
    end
    -- Rebuild from current verified caches, not unrelated unverified recording points.
    local points={}
    for savedId in pairs(savedGreenPoints) do
        local v=data.places[tostring(savedId)]
        if v then points[tostring(savedId)]={unit=v.unit,pos=v.pos,ground=v.ground} end
    end
    local ok,err=pcall(function()
        writefile(GREEN_POINTS_FILE,HttpService:JSONEncode({placeId=game.PlaceId,points=points}))
    end)
    if not ok then warn("MOBILE GREEN SAVE FAILED #"..id.." | "..tostring(err)) end
    return ok
end
