    local endAt=os.clock()+seconds
    repeat
        if stopped then return false end
        task.wait(math.max(0.025,math.min(0.13,endAt-os.clock())))
    until os.clock()>=endAt
    return not stopped
end
local function norm(s) return tostring(s or ""):gsub("<[^>]*>",""):lower():gsub("[^%w]","") end
local function txt(n)
    return (n:IsA("TextLabel") or n:IsA("TextButton") or n:IsA("TextBox")) and tostring(n.Text or "") or ""
end
local function vis(n)
    if not n or not n.Parent or not n:IsDescendantOf(pg) then return false end
    local p=n
    while p and p~=pg do
        if p:IsA("ScreenGui") and not p.Enabled then return false end
        if p:IsA("GuiObject") and not p.Visible then return false end
        p=p.Parent
    end
    return true
end
local function midpoint(n) return n.AbsolutePosition+n.AbsoluteSize/2 end
-- Money texts may use abbreviations ($1.2K) and localized spaces.
-- Never parse a level, damage, health or an unmarked number as cash.
local function moneyIn(t)
    local raw=tostring(t or ""):gsub("%s+","")
    local amount,suffix=raw:match("%$([%d,%.]+)([kKmMbB]?)")
    if not amount then return nil end
    if suffix=="" and amount:find("%.") then
        -- A decimal without K/M/B is not a whole-dollar cash amount.
        return nil
    end
    local normalized=amount:gsub(",","")
    local number=tonumber(normalized)
    if not number then return nil end
    local mult=({k=1e3,m=1e6,b=1e9})[suffix:lower()] or 1
    return math.floor(number*mult+0.5)
end
local function getInspect()
    local path=pg:FindFirstChild("Match")
    local inspect=path and path:FindFirstChild("InspectMenu",true)
    if inspect and vis(inspect) then return inspect end
    for _,n in ipairs(pg:GetDescendants()) do
        if norm(n.Name)=="inspectmenu" and vis(n) then return n end
    end
end
local function inspect(unit)
    local root=getInspect()
    if not root then return nil,"InspectMenu is not open (not proof of sleep)" end
    local found=false
    local level=nil
    for _,n in ipairs(root:GetDescendants()) do
        if n:IsA("GuiObject") and vis(n) then
            local text=txt(n)
            local normalized=norm(text)
            local expected=norm(modelNames[unit] or unit)
            -- Titles can append a level or suffix to the unit name.
            if normalized==expected or (normalized:sub(1,#expected)==expected
                and #normalized<=#expected+18) then found=true end
            local l=text:match("[Ll][Ee][Vv][Ee][Ll]%s*:?%s*(%d+)")
            if l then level=tonumber(l) end
        end
    end
    if not found then return nil,"wrong unit menu" end
    if not level then return nil,"level unreadable" end
    local button=root:FindFirstChild("UpgradeButton",true)
    if not button or not button:IsA("GuiButton") or not vis(button) then
        return nil,"UpgradeButton missing / menu locked"
    end
    -- Upgrade cost must belong to the Upgrade control, not Sell/Cash UI.
    local price,dis=nil,math.huge
    local at=midpoint(button)
    local picked=nil
    for _,n in ipairs(root:GetDescendants()) do
        if n:IsA("GuiObject") and vis(n) then
            local val=moneyIn(txt(n))
            if val then
                local path=n:GetFullName():lower()
                if not path:find("sell",1,true) and not path:find("refund",1,true) then
                    local nested=n:IsDescendantOf(button)
                    local parent=n.Parent
                    local parentName=parent and norm(parent.Name) or ""
                    local near=(midpoint(n)-at).Magnitude
                    local score=(nested and 0 or 100)
                        +(parentName:find("upgrade") and -40 or 0)
                        +(parentName:find("price") and -20 or 0)
                        +near
                    if (nested or near<130) and score<dis then
                        price,dis,picked=val,score,n
                    end
                end
            end
        end
    end
    if not price then return nil,"upgrade cost not uniquely attached to UpgradeButton / MAX" end
    return {root=root,button=button,level=level,cost=price}
end
-- Do NOT choose the nearest random $label. The old 449dp build could
-- mistake an upgrade cost or another UI currency for the player's balance.
local cashNode=nil
local lastCashSource=nil
local lastCashDiag=0
local function cashOnHud(root)
    local c=workspace.CurrentCamera
    local vp=c and c.ViewportSize or Vector2.new(1920,1080)
    local matchGui=pg:FindFirstChild("Match")
    local candidates={}
    for _,n in ipairs(pg:GetDescendants()) do
        if (n:IsA("TextLabel") or n:IsA("TextButton")) and vis(n)
            and (not root or not n:IsDescendantOf(root))
            and (not gui or not n:IsDescendantOf(gui)) then
            local raw=txt(n):gsub("%s+","")
            if raw:match("^%$[%d,%.]+[kKmMbB]?$" ) then
                local value=moneyIn(raw)
                if value then
                    local path=n:GetFullName():lower()
                    local blocked=false
                    for _,word in ipairs({"upgrade","sell","price","cost","shop","inventory","crate","reward","summon","pity","quest","troopselector","inspectmenu","purchase"}) do
                        if path:find(word,1,true) then blocked=true; break end
                    end
                    if not blocked then
                        local p=midpoint(n)
                        local name=norm(n.Name)
                        local par=n.Parent and norm(n.Parent.Name) or ""
                        local score=0
                        if name:find("cash") or name:find("money") or name:find("balance") then score=score+135 end
                        if par:find("cash") or par:find("money") or par:find("balance") then score=score+115 end
                        if matchGui and n:IsDescendantOf(matchGui) then score=score+65 end
                        if path:find("hud",1,true) or path:find("ingame",1,true) then score=score+30 end
                        if p.X>vp.X*.25 and p.X<vp.X*.75 and p.Y>vp.Y*.72 and p.Y<vp.Y*.99 then score=score+55 end
                        if n==cashNode then score=score+25 end
                        candidates[#candidates+1]={node=n,value=value,score=score,path=n:GetFullName()}
                    end
                end
            end
        end
    end
    table.sort(candidates,function(a,b) return a.score>b.score end)
    local best=candidates[1]
    local runner=candidates[2]
    local ambiguous=best and runner and math.abs(best.score-runner.score)<15 and best.value~=runner.value
    if best and best.score>=55 and not ambiguous then
        cashNode=best.node
        if lastCashSource~=best.path then
            lastCashSource=best.path
            log("CASH HUD LOCK | "..best.path.." | $"..best.value.." | score="..best.score)
        end
        return best.value
    end
    if os.clock()-lastCashDiag>8 then
        lastCashDiag=os.clock()
        local report={}
        for i=1,math.min(5,#candidates) do
            local q=candidates[i]
            report[#report+1]=q.node.Name.."=$"..q.value.."(score "..q.score..")"
        end
        log("CASH HUD UNSURE | "..table.concat(report,"; ").." | cannot safely read balance")
    end
    return nil
end
-- Detect a new match from visible in-game Wave 1 text + the real cash HUD.
-- Wave 1 alone is not sufficient; do not auto-start while still in the lobby.
local function matchActiveWave()
    if not game:IsLoaded() or not getRoot() then return nil end
    if not workspace:FindFirstChild("Troops") then return nil end
    local matchGui=pg:FindFirstChild("Match")
    if not matchGui then return nil end
    local wave=nil
    for _,node in ipairs(matchGui:GetDescendants()) do
        if (node:IsA("TextLabel") or node:IsA("TextButton")) and vis(node) then
            local t=norm(txt(node))
            local n=t:match("^wave0*(%d+)$")
            if n then
                local parsed=tonumber(n)
                if parsed and parsed>=1 then wave=parsed; break end
            end
        end
    end
    if not wave or cashOnHud(nil)==nil then return nil end
    return wave
end
local function matchWaveOneReady()
    return matchActiveWave()==1
end
local function modelLevel(model)
    if not model or not model.Parent then return nil end
    for _,name in ipairs({"Level","level","UpgradeLevel","upgradeLevel"}) do
        local v=model:GetAttribute(name)
        if type(v)=="number" then return v end
    end
    for _,n in ipairs(model:GetDescendants()) do
        if n:IsA("IntValue") or n:IsA("NumberValue") then
            if norm(n.Name)=="level" or norm(n.Name)=="upgradelevel" then
                return tonumber(n.Value)
            end
        elseif n:IsA("TextLabel") then
            local text=txt(n)
            local number=text:match("[Ll][Ee][Vv][Ee][Ll]%s*(%d+)")
            if number then return tonumber(number) end
        end
    end
end
local function modelPos(m)
    local success,where=pcall(function() return m:GetPivot().Position end)
    return success and where or nil
end
local function unitMatches(m,unit)
    return m and m:IsA("Model") and norm(m.Name)==norm(modelNames[unit] or unit)
end
local function worldXZ(p,q)
    return math.sqrt((p.X-q.X)^2+(p.Z-q.Z)^2)
end
local function modelsFor(unit)
    local folder=workspace:FindFirstChild("Troops")
    local out={}
    if folder then
        for _,m in ipairs(folder:GetChildren()) do
            if unitMatches(m,unit) then out[#out+1]=m end
        end
    end
    return out
end
local function knownUnitAlreadyPresent()
    -- Prevent auto-starting in the middle of an existing match.
    -- User can still press START NOW to override this conservative guard.
    for _,unit in ipairs({"pumpkin_farmer","chef_tv_man","medic_cameraman"}) do
        if #modelsFor(unit)>0 then return true end
    end
    return false
end
local function cframeFrom(a)
    if not a or #a~=12 then return nil end
    return CFrame.new(unpack(a))
end
local function cameraAt(t)
    local frames=data.camera
    if #frames==0 then return nil,nil end
    while cameraIndex<#frames-1 and frames[cameraIndex+1][1]<=t do cameraIndex=cameraIndex+1 end
    while cameraIndex>1 and frames[cameraIndex][1]>t do cameraIndex=cameraIndex-1 end
    local first=frames[cameraIndex]
    local second=frames[math.min(cameraIndex+1,#frames)]
    local a,b=cframeFrom(first[2]),cframeFrom(second[2])
    local dt=second[1]-first[1]
    local alpha=dt>0 and math.clamp((t-first[1])/dt,0,1) or 0
    return a:Lerp(b,alpha), first[3]+(second[3]-first[3])*alpha
end
local function setCamera(t,override)
    local c=workspace.CurrentCamera
    if not c then return end
    if c.CameraType~=Enum.CameraType.Scriptable then c.CameraType=Enum.CameraType.Scriptable end
    local cf,fov=cameraAt(t)
    if override then cf=override end
    if cf then c.CFrame=cf end
    if fov then c.FieldOfView=fov end
end
local function refreshReplayCamera()
    if not cameraBound or stopped then return end
    local current=cameraTimeline
    if camMoveDuration>0 then
        local alpha=math.clamp((os.clock()-camMoveWallStart)/camMoveDuration,0,1)
        current=camMoveFrom+(camMoveTo-camMoveFrom)*alpha
    end
    setCamera(cameraFrozen or current,cameraOverride)
end
local function bindCamera()
    cam=workspace.CurrentCamera
    if not cam then return end
    originalCameraType=cam.CameraType
    originalFov=cam.FieldOfView
    cameraIndex=1
    cameraBound=true
    -- Foreground: update immediately before rendering, matching v0.8.4
    -- (Heartbeat-only introduced a possible hit-testing / projection race).
    RunService:BindToRenderStep(cameraBind,Enum.RenderPriority.Camera.Value+20,function()
        if windowFocused then refreshReplayCamera() end
    end)
    -- Background: rendering might be throttled; keep best-effort camera updates.
    local elapsed=0
    cameraConnection=RunService.Heartbeat:Connect(function(dt)
        if not cameraBound or stopped or windowFocused then return end
        elapsed=elapsed+(dt or .03)
        if elapsed<1/15 then return end
        elapsed=0
        refreshReplayCamera()
    end)
end
local function unbindCamera()
    cameraBound=false
    pcall(function() RunService:UnbindFromRenderStep(cameraBind) end)
    if cameraConnection then cameraConnection:Disconnect(); cameraConnection=nil end
    local c=workspace.CurrentCamera
    if c and originalCameraType then c.CameraType=originalCameraType end
    if c and originalFov then c.FieldOfView=originalFov end
end
-- Executor keypress/keyrelease use WINDOWS virtual-key codes (VK),
-- not Enum.KeyCode.Value (which has different numbers for many keys).
local vkCodes={
    W=0x57,A=0x41,S=0x53,D=0x44,
    One=0x31,Two=0x32,Three=0x33,Four=0x34,Five=0x35,
    E=0x45,Q=0x51,R=0x52,F=0x46,
    Space=0x20,LeftShift=0x10,RightShift=0x10,
    LeftControl=0x11,RightControl=0x11,Escape=0x1B,
}
local function sendKey(key,down)
    local enum=Enum.KeyCode[key]
    if not enum then return false,"unknown recorded key "..tostring(key) end
    local attempts={}
    if CONFIG.backgroundMode and not windowFocused then
        if not VIM then return false,"BACKGROUND: VIM missing (no OS keys sent)" end
        local sent,err=pcall(function() VIM:SendKeyEvent(down,enum,false,game) end)
        if sent then return true,"VIM BACKGROUND" end
        return false,"BACKGROUND: VIM rejected key "..tostring(key)..": "..tostring(err)
    end
    if keyboardMode=="AUTO" or keyboardMode=="EXECUTOR" then
        local f=down and keypress or keyrelease
        local vk=vkCodes[key]
        if type(f)=="function" and vk then
            local ok,err=pcall(f,vk)
            if ok then return true,"executor VK "..tostring(vk) end
            attempts[#attempts+1]="executor: "..tostring(err)
        else
            attempts[#attempts+1]="executor VK function/key unavailable"
        end
    end
    if keyboardMode=="AUTO" or keyboardMode=="VIM" then
        if VIM then
            local ok,err=pcall(function() VIM:SendKeyEvent(down,enum,false,game) end)
            if ok then return true,"VirtualInputManager" end
            attempts[#attempts+1]="VIM: "..tostring(err)
        else
            attempts[#attempts+1]="VIM unavailable"
        end
    end
    return false,table.concat(attempts,"; ")
end
local function suspendHeldKeys()
    local a={}
    for key in pairs(keysHeld) do
        local ok=sendKey(key,false)
        if ok then a[#a+1]=key end
    end
    if #a>0 then log("PAUSE HELD KEYS for verified placement/upgrade: "..table.concat(a,",")) end
    return a
end
local function resumeHeldKeys(a)
    if stopped then return end
    for _,key in ipairs(a) do
        if keysHeld[key] then
            local ok,err=sendKey(key,true)
            if not ok then error("cannot resume key "..key..": "..tostring(err)) end
        end
    end
end
-- A full-screen transparent GuiButton catches stray physical clicks while
-- Roblox is focused. A separate high-DisplayOrder GUI keeps the STOP button
-- accessible. During an intentional replay click the shield is briefly hidden.
-- Moving the physical cursor is not intercepted at the OS level.
-- The shield is suspended across placement preparation / click to avoid stealing VIM input.
local function mouseMovementSink(actionName,inputState,inputObject)
    if running and CONFIG.mouseShield and windowFocused and mouseShieldSuspend==0 then
        return Enum.ContextActionResult.Sink
    end
    return Enum.ContextActionResult.Pass
end
updateMouseShield=function()
    local enabled=running and not stopped and CONFIG.mouseShield and windowFocused and mouseShieldSuspend==0
    if mouseShieldGui then
        mouseShieldGui.Enabled=not not enabled
        if mouseShieldSurface then
            mouseShieldSurface.Active=not not enabled
            mouseShieldSurface.Visible=not not enabled
        end
    end
    if mouseShieldButton then
        mouseShieldButton.Text="MOUSE SHIELD: "..(CONFIG.mouseShield and "ON" or "OFF")
        mouseShieldButton.BackgroundColor3=CONFIG.mouseShield
            and Color3.fromRGB(28,130,110) or Color3.fromRGB(96,72,115)
    end
end
local function makeMouseShield()
    mouseShieldGui=Instance.new("ScreenGui")
    mouseShieldGui.Name="LegacyTTD_MouseShield_v0817"
    mouseShieldGui.IgnoreGuiInset=true
    mouseShieldGui.ResetOnSpawn=false
    mouseShieldGui.DisplayOrder=499999 -- BELOW our GUI but ABOVE game UI
    mouseShieldGui.Enabled=false
    mouseShieldGui.Parent=pg
    mouseShieldSurface=Instance.new("TextButton")
    mouseShieldSurface.Name="CatchAccidentalClicks"
    mouseShieldSurface.Size=UDim2.fromScale(1,1)
    mouseShieldSurface.BackgroundTransparency=1
    mouseShieldSurface.Text=""
    mouseShieldSurface.BorderSizePixel=0
    mouseShieldSurface.AutoButtonColor=false
    mouseShieldSurface.Active=true
    mouseShieldSurface.ZIndex=1
    mouseShieldSurface.Parent=mouseShieldGui
    -- IMPORTANT: Do not bind ContextActionService mouse motion here.
    -- That hook was introduced with the placement regression and can interfere
    -- with the game's preview tracking synthetic mouse movement. The optional
    -- GUI intercept alone catches accidental foreground clicks when enabled.
end
local function beginAutoMouseInput()
    local wasUnblocked=mouseShieldSuspend>0
    mouseShieldSuspend=mouseShieldSuspend+1
    updateMouseShield()
    -- Setting ScreenGui.Enabled=false is not guaranteed to update GUI hit-testing
    -- instantly. Wait two scheduler ticks before synthetic mouse input.
    if not wasUnblocked and windowFocused and CONFIG.mouseShield then
        task.wait(.07)
    end
end
local function endAutoMouseInput()
    if mouseShieldSuspend<=0 then mouseShieldSuspend=0; return end
    -- Allow mouse-up dispatch to finish before restoring the intercepting GUI.
    if mouseShieldSuspend==1 and windowFocused and CONFIG.mouseShield then
        task.wait(.09)
    end
    mouseShieldSuspend=math.max(0,mouseShieldSuspend-1)
    updateMouseShield()
end
-- Keep input move + click in the SAME implementation. Do not mix VIM cursor
-- and native executor click (they may target different screen coordinates).
local function tapRawWithMethod(x,y,method)
    x,y=math.floor(x+.5),math.floor(y+.5)
    local viewport=liveViewport()
    if x<0 or y<0 or x>viewport.X or y>viewport.Y then
        return false,"outside Roblox viewport: "..x..","..y
    end
    if CONFIG.backgroundMode and not windowFocused then
        if not VIM then return false,"BACKGROUND cannot click: VIM unavailable" end
        method="VIM" -- never move/click an unrelated app window
    end
    if method=="TOUCH" or method=="TOUCH_DRAG" then
        if not VIM then return false,"VirtualInputManager missing" end
        local beginCount=mobileTouchSeen.began
        local endCount=mobileTouchSeen.ended
        -- In some mobile games the preview is updated on TouchMoved, not on
        -- a stationary click. A short drag ending at the requested point
        -- supplies Began -> Changed -> Ended while staying on the same patch.
        local drag=method=="TOUCH_DRAG"
        local startX=drag and math.min(viewport.X-4,x+13) or x
        local startY=drag and math.min(viewport.Y-4,y+11) or y
        local touchId=drag and 19 or 1
        local down,downErr=pcall(function() VIM:SendTouchEvent(touchId,0,startX,startY) end)
        if not down then return false,"TOUCH begin rejected: "..tostring(downErr) end
        delayCheck(.09)
        if drag then
            local moved,mErr=pcall(function() VIM:SendTouchEvent(touchId,1,x+4,y+3) end)
            if not moved then
                pcall(function() VIM:SendTouchEvent(touchId,2,startX,startY) end)
                return false,"TOUCH changed rejected: "..tostring(mErr)
            end
            delayCheck(.12)
            pcall(function() VIM:SendTouchEvent(touchId,1,x,y) end)
            delayCheck(.13)
        else
            delayCheck(.14)
        end
        local up,upErr=pcall(function() VIM:SendTouchEvent(touchId,2,x,y) end)
        if not up then return false,"TOUCH end rejected: "..tostring(upErr) end
        delayCheck(.06)
        log("MOBILE TOUCH DELIVERY | method="..method
            .." | UIS began="..(mobileTouchSeen.began-beginCount)
            .." ended="..(mobileTouchSeen.ended-endCount)
            .." | VIM sent=true (not proof of gameplay input)")
        return true,method
    end
    if method=="VIM" then
        if not VIM then return false,"VirtualInputManager missing" end
        local moved,mErr=pcall(function() VIM:SendMouseMoveEvent(x,y,game) end)
        if not moved then return false,"VIM move: "..tostring(mErr) end
        if not delayCheck(.08) then return false,"stopped" end
        -- Re-aim directly before click in case user touched the physical mouse.
        pcall(function() VIM:SendMouseMoveEvent(x,y,game) end)
        local down,dErr=pcall(function() VIM:SendMouseButtonEvent(x,y,0,true,game,0) end)
        if not down then return false,"VIM mouse down: "..tostring(dErr) end
        delayCheck(.12)
        local up,uErr=pcall(function() VIM:SendMouseButtonEvent(x,y,0,false,game,0) end)
        if not up then return false,"VIM mouse up: "..tostring(uErr) end
        return true,"VIM"
    end
    if method=="EXECUTOR" then
        if not windowFocused then return false,"Roblox unfocused: OS mouse disabled" end
        if type(mousemoveabs)~="function" then return false,"mousemoveabs unavailable" end
        local moved,mErr=pcall(mousemoveabs,x,y)
        if not moved then return false,"executor move: "..tostring(mErr) end
        if not delayCheck(.24) then return false,"stopped" end
        if type(mouse1press)=="function" and type(mouse1release)=="function" then
            local down,dErr=pcall(mouse1press)
            if not down then return false,"executor mouse1press: "..tostring(dErr) end
            delayCheck(.12)
            local up,uErr=pcall(mouse1release)
            if not up then return false,"executor mouse1release: "..tostring(uErr) end
            return true,"EXECUTOR press/release"
        elseif type(mouse1click)=="function" then
            local clicked,cErr=pcall(mouse1click)
            return clicked,clicked and "EXECUTOR click" or tostring(cErr)
        end
        return false,"executor mouse1click/press/release unavailable"
    end
    return false,"unknown mouse method "..tostring(method)
end
local function tapWithMethod(x,y,method)
    beginAutoMouseInput()
    local completed,ok,why=pcall(tapRawWithMethod,x,y,method)
    endAutoMouseInput()
    if not completed then return false,"input error: "..tostring(ok) end
    return ok,why
end
local function tap(x,y)
    local ok,why=tapWithMethod(x,y,preferredClickMode)
    if ok then return true,why end
    if CONFIG.backgroundMode and not windowFocused then
        return false,"VIM BACKGROUND input failed: "..tostring(why)
    end
    local other=preferredClickMode=="VIM" and "EXECUTOR" or "VIM"
    if MOBILE_449 and VIM and other=="EXECUTOR" then
        return false,"Android VIM click failed: "..tostring(why)
    end
    local fallback,result=tapWithMethod(x,y,other)
    if fallback then
        log("INPUT FALLBACK "..other.." after "..tostring(why))
        preferredClickMode=other
        return true,result
    end
    return false,"primary "..tostring(why).."; fallback "..tostring(result)
end
local function scale(x,y)
    local v=liveViewport()
    local rw,rh=data.viewport[1],data.viewport[2]
    -- Roblox's camera FOV is vertical. Preserve recording's vertical scale,
    -- then add the width difference equally on both sides (20:9 landscape).
    local ratio=v.Y/rh
    local mx=(v.X-rw*ratio)*0.5
    return math.floor(mx+x*ratio+0.5),math.floor(y*ratio+0.5)
end
-- Recorded mouse click at t=0.811s (1036,88) is the top-center Auto Skip
-- toggle. We intentionally replay ONLY this UI click; gameplay clicks stay filtered.
-- Read its actual red/green indicator first so a second run never turns it OFF.
local function autoSkipColorState(c)
    if not c then return nil end
    local r,g,b=c.R,c.G,c.B
    if g>.46 and g>r*1.48 and g>b*1.4 then return "GREEN" end
    if r>.50 and r>g*1.5 and r>b*1.32 then return "RED" end
    return nil
end
-- Auto Skip may have duplicate TextLabels under panels that are technically
-- Visible=true while their coordinates are ABOVE THE SCREEN.  A recent log
-- showed AutoSkipText at (384,-13), and the real OnAndOff button was missed.
-- Never send a mouse click to such a stale/offscreen label.
local function autoSkipOnScreen(n)
    if not n or not n:IsA("GuiObject") or not vis(n) then return false end
    local camera=workspace.CurrentCamera
    local vp=camera and camera.ViewportSize or Vector2.new(1920,1080)
    if vp.X<100 or vp.Y<100 then return false end
    local p=n.AbsolutePosition
    local sz=n.AbsoluteSize
    if sz.X<9 or sz.Y<9 then return false end
    local mid=midpoint(n)
    return mid.X>4 and mid.Y>4 and mid.X<vp.X-4 and mid.Y<vp.Y-4
end
local function autoSkipColorOf(n)
    if not n then return nil end
    local color=nil
    if n.BackgroundTransparency<.85 then
        color=autoSkipColorState(n.BackgroundColor3)
    end
    if not color and (n:IsA("ImageButton") or n:IsA("ImageLabel"))
        and n.ImageTransparency<.85 then
        color=autoSkipColorState(n.ImageColor3)
    end
    -- Some versions color a child Frame instead of the button itself.
    if not color then
        for _,c in ipairs(n:GetChildren()) do
            if c:IsA("GuiObject") and vis(c) and c.BackgroundTransparency<.85 then
                color=autoSkipColorState(c.BackgroundColor3)
                if color then break end
            end
        end
    end
    return color
end
local function locateAutoSkip()
    local camera=workspace.CurrentCamera
    local vp=camera and camera.ViewportSize or Vector2.new(1920,1080)
    local labels={}
    local buttons={}
    -- GUI absolute positions are already in the client's current viewport;
    -- do NOT scale them from the 1920x1080 recording or use stale coordinates.
    for _,n in ipairs(pg:GetDescendants()) do
        if autoSkipOnScreen(n) and (not gui or not n:IsDescendantOf(gui)) then
            local p=midpoint(n)
            if p.Y<vp.Y*.23 then
                if (n:IsA("TextLabel") or n:IsA("TextButton"))
                    and norm(txt(n))=="autoskip" then
                    labels[#labels+1]=n
                end
                -- Unlike label-based proximity search, find OnAndOff by
                -- its exact name FIRST.  This name was confirmed in a
                -- successful log of this game's own GUI.
                if n:IsA("GuiButton") and norm(n.Name)=="onandoff"
                    and n.AbsoluteSize.X<=110 and n.AbsoluteSize.Y<=110 then
                    buttons[#buttons+1]=n
                end
            end
        end
    end
    local bestLabel=nil
    local labelScore=math.huge
    for _,label in ipairs(labels) do
        local p=midpoint(label)
        -- Prefer the top-center HUD label, not a side-panel clone.
        local score=math.abs(p.X-vp.X*.57)+p.Y*.4
        if score<labelScore then bestLabel,labelScore=label,score end
    end
    local bestIndicator=nil
    local bestScore=math.huge
    for _,button in ipairs(buttons) do
        local p=midpoint(button)
        local score=math.abs(p.X-vp.X*.63)+p.Y*.25
        if bestLabel then
            local lab=midpoint(bestLabel)
            local near=(p.X>=lab.X+10 and p.X<=lab.X+210
                and math.abs(p.Y-lab.Y)<=70)
            if near then
                score=score-1000+math.abs(p.X-lab.X-85)*.6
            end
        end
        if score<bestScore then bestIndicator,bestScore=button,score end
    end
    -- Fallback: when the game uses an unhelpful name for the colored square,
    -- find only visible red/green controls to the RIGHT of the valid label.
    if not bestIndicator and bestLabel then
        local mid=midpoint(bestLabel)
        local right=bestLabel.AbsolutePosition.X+bestLabel.AbsoluteSize.X
        for _,n in ipairs(pg:GetDescendants()) do
            if autoSkipOnScreen(n) and n~=bestLabel
                and (not gui or not n:IsDescendantOf(gui)) then
                local p=midpoint(n)
                local sz=n.AbsoluteSize
                if sz.X>=12 and sz.Y>=12 and sz.X<=96 and sz.Y<=96
                    and p.X>mid.X+12 and p.X<right+140
                    and math.abs(p.Y-mid.Y)<50
                    and autoSkipColorOf(n) then
                    local score=math.abs(p.X-right-17)+2*math.abs(p.Y-mid.Y)
                    if score<bestScore then bestIndicator,bestScore=n,score end
                end
            end
        end
    end
    -- In small Roblox windows the top HUD may be shifted ABOVE the viewport.
    -- firesignal can activate a genuine OnAndOff GuiButton even while offscreen;
    -- clicking such negative coordinates with the physical mouse is unsafe.
    if not bestIndicator then
        local allLabels={}
        for _,n in ipairs(pg:GetDescendants()) do
            if (n:IsA("TextLabel") or n:IsA("TextButton")) and vis(n)
                and norm(txt(n))=="autoskip"
                and (not gui or not n:IsDescendantOf(gui)) then
                allLabels[#allLabels+1]=n
            end
        end
        local offscreenScore=math.huge
        for _,n in ipairs(pg:GetDescendants()) do
            if n:IsA("GuiButton") and vis(n)
                and norm(n.Name)=="onandoff"
                and n.AbsoluteSize.X>=9 and n.AbsoluteSize.X<=110
                and n.AbsoluteSize.Y>=9 and n.AbsoluteSize.Y<=110
                and (not gui or not n:IsDescendantOf(gui)) then
                local pos=midpoint(n)
                for _,label in ipairs(allLabels) do
                    local lp=midpoint(label)
                    local dx=pos.X-lp.X
                    local dy=math.abs(pos.Y-lp.Y)
                    if dx>=5 and dx<=230 and dy<=85 then
                        local score=math.abs(dx-85)+dy*2
                        if score<offscreenScore then
                            bestIndicator,bestLabel,offscreenScore=n,label,score
                        end
                    end
                end
            end
        end
    end
    return bestLabel,bestIndicator,autoSkipColorOf(bestIndicator)
end
-- Prefer the actual OnAndOff GuiButton over large labels/overlays.
local function autoSkipButtons(label,indicator)
    local out={}
    local seen={}
    local function add(n,score)
        if not n or seen[n] or not n:IsA("GuiButton") then return end
        -- Offscreen exact-name OnAndOff is eligible for GUI signals ONLY.
        if not autoSkipOnScreen(n) and not
            (norm(n.Name)=="onandoff" and vis(n)) then return end
        seen[n]=true
        out[#out+1]={node=n,score=score}
    end
    if indicator then
        if indicator:IsA("GuiButton") then add(indicator,-1000) end
        local parent=indicator.Parent
        for i=1,3 do
            if not parent or parent==pg then break end
            add(parent,-200+i)
            parent=parent.Parent
        end
    end
    if label then
        add(label,-900)
        local parent=label.Parent
        for i=1,3 do
            if not parent or parent==pg then break end
            add(parent,-100+i)
            parent=parent.Parent
        end
    end
    -- Do not click broad input overlays: only a small GuiButton that
    -- overlaps the actual toggle can be a candidate.
    if indicator then
        local q=midpoint(indicator)
        for _,n in ipairs(pg:GetDescendants()) do
            if n:IsA("GuiButton") and autoSkipOnScreen(n)
                and (not gui or not n:IsDescendantOf(gui)) then
                local pos,sz=n.AbsolutePosition,n.AbsoluteSize
                if sz.X<=310 and sz.Y<=115 and sz.X>=9 and sz.Y>=9
                    and q.X>=pos.X and q.X<=pos.X+sz.X
                    and q.Y>=pos.Y and q.Y<=pos.Y+sz.Y then
                    add(n,-50+math.abs((midpoint(n)-q).Magnitude)*.03)
                end
            end
        end
    end
    table.sort(out,function(a,b) return a.score<b.score end)
    return out
end
local function autoSkipWaitGreen(seconds)
    local untilAt=os.clock()+seconds
    repeat
        if stopped then return false end
        local _,_,state=locateAutoSkip()
        if state=="GREEN" then return true end
        task.wait(.12)
    until os.clock()>=untilAt
    return false
end
local function autoSkipLogTarget(n)
    if not n then return "nil" end
    local pos=midpoint(n)
    return n.Name.." ["..n.ClassName.."] @"..math.floor(pos.X)..","..math.floor(pos.Y)
end
local function ensureAutoSkipGreen(recordedX,recordedY)
    local label,indicator,state
    -- Roblox HUD may initially be offscreen: inspect true named controls and
    -- wait for a readable red/green toggle before sending signals.
    for attempt=1,65 do
        if stopped then return false,"stopped" end
        label,indicator,state=locateAutoSkip()
        if indicator and state then break end
        if attempt==1 or attempt==20 or attempt==45 then
            log("AUTO SKIP WAIT VISIBLE TOGGLE | label="..tostring(label and autoSkipLogTarget(label) or "nil")
                .." | indicator="..tostring(indicator and autoSkipLogTarget(indicator) or "nil"))
        end
        task.wait(.18)
    end
    if not indicator or not state then
        return false,"No red/green Auto Skip OnAndOff found; never clicking offscreen label"
    end
    log("AUTO SKIP UI label="..autoSkipLogTarget(label)
        .." | indicator="..autoSkipLogTarget(indicator)
        .." | state="..tostring(state))
    if state=="GREEN" then
        log("AUTO SKIP GREEN confirmed (already on)")
        return true,"already GREEN"
    end
    -- Signal path is independent of cursor hitboxes and can operate on UI
    -- whose colored square is only a visual indicator.
    local buttons=autoSkipButtons(label,indicator)
    log("AUTO SKIP GUI candidates="..#buttons)
    for i=1,math.min(4,#buttons) do
        log("AUTO SKIP target #"..i..": "..autoSkipLogTarget(buttons[i].node))
    end
    if type(firesignal)=="function" then
        -- v14: One real button signal per try, then WAIT for GUI confirmation.
        -- The old .45s timeout could fire Click AND Activated in quick succession,
        -- toggling the same switch twice or racing a delayed state update.
        -- Only send a new signal while the indicator is positively RED.
        for round=1,2 do
            for i=1,math.min(1,#buttons) do
                local button=buttons[i].node
                for _,signalName in ipairs({"Activated","MouseButton1Click"}) do
                    if stopped then return false,"stopped" end
                    local _,_,observed=locateAutoSkip()
                    if observed=="GREEN" then
                        log("AUTO SKIP GREEN confirmed after callback")
                        return true,"GREEN"
                    end
                    if observed~="RED" then
                        log("AUTO SKIP STATE UNKNOWN | not toggling blindly")
                        return false,"Auto Skip state not readable; no blind double toggle"
                    end
                    local ok,err=pcall(function()
                        if signalName=="Activated" then
                            firesignal(button.Activated,nil,1)
                        else
                            firesignal(button.MouseButton1Click)
                        end
                    end)
                    log("AUTO SKIP v14 "..signalName.." | round="..round
                        .." | target="..autoSkipLogTarget(button)
                        .." | "..(ok and "sent" or tostring(err)))
                    if ok and autoSkipWaitGreen(.95) then
                        log("AUTO SKIP GREEN confirmed by GUI signal")
                        return true,"GUI "..signalName
                    end
                end
            end
        end
    else
        log("AUTO SKIP: firesignal not available; using mouse click hitboxes")
    end
    -- If signals were not attached, try the actual GUI hitbox, followed by
    -- the label and indicator. Re-read state BEFORE every click to avoid OFF.
    local targets={}
    local seen={}
    local function addTarget(n,kind)
        if not n or seen[n] or not autoSkipOnScreen(n) then return end
        seen[n]=true
        local q=midpoint(n)
        targets[#targets+1]={x=q.X,y=q.Y,kind=kind,n=n}
    end
    for i=1,math.min(3,#buttons) do addTarget(buttons[i].node,"BUTTON") end
    -- Only click the REAL on-screen button. A TextLabel is informational and
    -- may be offscreen or not clickable. Never fall back to old 1920x1080 coords.
    addTarget(indicator,"COLOR")
    if #targets==0 then
        return false,"Auto Skip not GREEN and toggle is offscreen; mouse fallback disabled"
    end
    for i=1,math.min(5,#targets) do
        if stopped then return false,"stopped" end
        local _,_,before=locateAutoSkip()
        if before=="GREEN" then
            log("AUTO SKIP GREEN confirmed")
            return true,"GREEN before click"
        end
        local q=targets[i]
        local mode=(i==5) and "EXECUTOR" or "VIM"
        local ok,why=tapWithMethod(q.x,q.y,mode)
        log("AUTO SKIP "..q.kind.." CLICK #"..i.." via "..mode
            .." @"..math.floor(q.x)..","..math.floor(q.y)
            .." | "..tostring(why))
        if ok and autoSkipWaitGreen(.55) then
            log("AUTO SKIP GREEN confirmed by "..q.kind.." click")
            return true,"click "..q.kind
        end
    end
    local _,_,after=locateAutoSkip()
    return false,"Auto Skip still "..tostring(after).."; GUI paths logged for diagnosis"
end
local function project(pos)
    local c=workspace.CurrentCamera
    if not c then return nil end
    local p,inView=c:WorldToViewportPoint(pos)
    local v=c.ViewportSize
    if not inView or p.X<60 or p.X>v.X-60 or p.Y<60 or p.Y>v.Y-60 then return nil end
    return math.floor(p.X+.5),math.floor(p.Y+.5)
end
local function freeze(t)
    cameraFrozen=t
    cameraOverride=nil
    setCamera(t)
    task.wait(.07)
end
local function claimedModel(m)
    for _,known in pairs(placedModels) do
        if known==m then return true end
    end
    return false
end
local function matchingAtRecordedSpot(info,baseline)
    local want=Vector3.new(info.pos[1],info.pos[2],info.pos[3])
    local near={}
    for _,model in ipairs(modelsFor(info.unit)) do
        if not claimedModel(model) and (not baseline or not baseline[model]) then
            local p=modelPos(model)
            local tolerance=(MOBILE_449 and info==data.places["5"])
                and 0.85 or CONFIG.placementRadiusXZ
            if p and worldXZ(p,want)<=tolerance then
                near[#near+1]=model
            end
        end
    end
    if #near==1 then return near[1] end
    if #near>1 then return nil,"multiple unclaimed units at same recorded point" end
end
-- SAFETY v0.8.14: the old script looked ONLY for a new model within 2
-- studs. At Chef TV #9 its log showed existing chef_tv_man 2 -> 3 during
-- overhead recovery, yet it kept sending clicks. Detect *every* new troop,
-- including the wrong unit or a correct unit far from the intended point.
-- One spawned model must end further placement clicks immediately.
local function freshPlacedTroop(beforeAll,expectedUnit,goal,id)
    local fresh={}
    for _,kind in ipairs({"pumpkin_farmer","chef_tv_man","medic_cameraman"}) do
        for _,m in ipairs(modelsFor(kind)) do
            if not beforeAll[m] and not claimedModel(m) then
                fresh[#fresh+1]={kind=kind,model=m,pos=modelPos(m)}
            end
        end
    end
    if #fresh==0 then return nil,nil,nil end
    if #fresh>1 then
        local names={}
        for i=1,math.min(#fresh,4) do
            names[#names+1]=fresh[i].kind
        end
        return nil,"UNSAFE: "..#fresh.." NEW troops detected ("..table.concat(names,",")
            .."); STOPPED so no extra units are placed",nil
    end
    local spawned=fresh[1]
    if spawned.kind~=expectedUnit then
        return nil,"WRONG UNIT SPAWNED: expected "..expectedUnit
            .." but got "..spawned.kind.."; STOPPED to avoid duplicates",nil
    end
    if not spawned.pos then
        return nil,"NEW "..expectedUnit.." exists but pivot not ready; STOPPED to avoid duplicate clicks",nil
    end
    local distance=worldXZ(spawned.pos,goal)
    if MOBILE_449 and id==1 then
        log(string.format("FIRST TROOP WORLD POSITION | observed X=%.3f Z=%.3f | recorded X=%.3f Z=%.3f | drift=%.3f studs",
            spawned.pos.X,spawned.pos.Z,goal.X,goal.Z,distance))
    end
    local tolerance=(MOBILE_449 and id==5) and 0.85
        or ((MOBILE_449 and id==1) and CONFIG.mobileFirstToleranceXZ
        or CONFIG.placementNearbyAcceptXZ)
    if MOBILE_449 and id==5 then
        log(string.format("CHEF RECORDED SPAWN #5 | actual=(%.3f,%.3f) recorded=(%.3f,%.3f) offset=%.3f max=%.2f",
            spawned.pos.X,spawned.pos.Z,goal.X,goal.Z,distance,tolerance))
    end
    if MOBILE_449 and id==1 and distance>1.5 and distance<=tolerance then
        log(string.format("MOBILE FIRST SPAWN ACCEPTED | server-confirmed troop | %.3f studs from requested point; updating next-run coordinates",distance))
    end
    if distance>tolerance then
        return nil,string.format(
            "WRONG POSITION: a new %s spawned at X=%.2f Z=%.2f, %.2f studs from target X=%.2f Z=%.2f; STOPPED WITHOUT ANOTHER CLICK",
            expectedUnit,spawned.pos.X,spawned.pos.Z,distance,goal.X,goal.Z),distance
    end
    return spawned.model,nil,distance
end

-- On a background window the executor/VIM may report that a numeric key was
-- sent while the in-game placement preview was silently lost.  Reassert selection
-- by switching to a DIFFERENT slot and back.  A same-slot key alone can toggle
-- the preview OFF.  Never count a placement until a new model is observed.
-- Redmi/Delta: the five real troop buttons are named InteractiveButton.
-- Their labels do not include slot numbers; the previous text-based lookup
-- always returned 0 candidates and silently reverted to PC keyboard keys.
CONFIG.orderedMobileButtons=function()
    local panel=pg:FindFirstChild("TroopsSelector",true)
    if not panel then return {},"TroopsSelector missing" end
    local buttons={}
    for _,b in ipairs(panel:GetDescendants()) do
        if b:IsA("GuiButton") and b.Name=="InteractiveButton"
            and vis(b) and b.AbsoluteSize.X>1 and b.AbsoluteSize.Y>1 then
            buttons[#buttons+1]=b
        end
    end
    if #buttons~=5 then
        return buttons,"expected 5 visible InteractiveButton slots, found "..#buttons
    end
    -- Resolve order by visible physical layout, not a button's generic name.
    -- Landscape mobile selectors are normally horizontal, portrait ones vertical.
    local minx,maxx,miny,maxy=math.huge,-math.huge,math.huge,-math.huge
    for _,b in ipairs(buttons) do
        local c=midpoint(b)
        minx=math.min(minx,c.X);maxx=math.max(maxx,c.X)
        miny=math.min(miny,c.Y);maxy=math.max(maxy,c.Y)
    end
    local horizontal=(maxx-minx)>=(maxy-miny)
    table.sort(buttons,function(a,b)
        local x,y=midpoint(a),midpoint(b)
        if horizontal then
            if math.abs(x.X-y.X)>2 then return x.X<y.X end
            return x.Y<y.Y
        end
        if math.abs(x.Y-y.Y)>2 then return x.Y<y.Y end
        return x.X<y.X
    end)
    return buttons,horizontal and "left-to-right" or "top-to-bottom"
end
CONFIG.mobileHotbarReport=function()
    if not MOBILE_449 then return end
    local buttons,order=CONFIG.orderedMobileButtons()
    log("MOBILE HOTBAR ORDER | "..tostring(order).." | buttons="..#buttons)
    for i,b in ipairs(buttons) do
        local c=midpoint(b)
        log(string.format("MOBILE SLOT %d | %s | parent=%s | center=%d,%d | layout=%d | visible=%s",
            i,b:GetFullName(),b.Parent and b.Parent.Name or "?",
            math.floor(c.X+.5),math.floor(c.Y+.5),b.Parent and b.Parent:IsA("GuiObject") and b.Parent.LayoutOrder or -1,
            tostring(vis(b))))
    end
end
-- v12 LANDSCAPE 921x449: only one hotbar activation per selection call.
-- v10/v11 could call TOUCH, VIM and a GUI callback in sequence. If the first
-- action equipped a unit but was not detected by our probe, the next action
-- toggled the SAME slot back OFF. This is why world aiming alone could not help.
CONFIG.mobileEquipTries={}
CONFIG.mobilePreviewWitness=function(unit)
    -- A preview is usually a local Model outside the server Troops folder.
    -- The model's name and parent vary by game version. This is a POSITIVE
    -- witness only; an empty result is UNKNOWN, never proof that it is absent.
    local wanted=({pumpkin_farmer="pumpkinfarmer",chef_tv_man="cheftvman",
        medic_cameraman="mediccameraman"})[unit]
    if not wanted then return false,"unknown-unit" end
    local realTroops=workspace:FindFirstChild("Troops")
    local names={}
    local inspected=0
    for _,obj in ipairs(workspace:GetDescendants()) do
        if obj:IsA("Model") and (not realTroops or not obj:IsDescendantOf(realTroops)) then
            inspected=inspected+1
            local nm=obj.Name:lower():gsub("[^a-z]","")
            local parent=obj.Parent and obj.Parent.Name:lower() or ""
            if nm:find(wanted,1,true)
                or ((parent:find("preview",1,true) or parent:find("placing",1,true)
                    or parent:find("ghost",1,true)) and nm:find("troop",1,true)) then
                names[#names+1]=obj:GetFullName()
                if #names>=4 then break end
            end
        end
    end
    return #names>0,(#names>0 and table.concat(names,"; ") or
        ("unknown; scanned="..inspected.." non-server models"))
end
CONFIG.mobileSlotVisual=function(b)
    local snapshots={}
    local function sample(n)
        if not n or not n:IsA("GuiObject") then return end
        local clr=n.BackgroundColor3
        snapshots[#snapshots+1]=n.Name..":"..tostring(n.Visible)
            ..":"..math.floor(clr.R*255+0.5)..","..math.floor(clr.G*255+0.5)
        if n:IsA("ImageLabel") or n:IsA("ImageButton") then
            local ic=n.ImageColor3
            snapshots[#snapshots+1]="I"..n.Name..":"..math.floor(ic.R*255+.5)..","..math.floor(ic.G*255+.5)
        end
    end
    sample(b);sample(b.Parent)
    if b.Parent then
        for _,n in ipairs(b.Parent:GetChildren()) do
            if n:IsA("GuiObject") then sample(n) end
            if n:IsA("UIStroke") then
                snapshots[#snapshots+1]="S"..n.Name..":"..tostring(n.Enabled)..":"..tostring(n.Color)
            end
        end
    end
    table.sort(snapshots)
    return table.concat(snapshots,"|")
end
CONFIG.selectMobileUnit=function(unit)
    if not MOBILE_449 then return false,"not mobile" end
    local index=({pumpkin_farmer=1,chef_tv_man=2,medic_cameraman=3})[unit]
    if not index then return false,"unknown unit "..tostring(unit) end
    local buttons,order=CONFIG.orderedMobileButtons()
    if #buttons~=5 then
        CONFIG.mobileHotbarReport()
        return false,"expected 5 troop buttons: "..tostring(order)
    end
    local v=liveViewport()
    if v.X<=v.Y then
        return false,string.format("LANDSCAPE REQUIRED: viewport %.0fx%.0f",v.X,v.Y)
    end
    local b=buttons[index]
    local c=midpoint(b)
    if c.X<4 or c.Y<4 or c.X>v.X-4 or c.Y>v.Y-4 then
        return false,"slot center outside viewport"
    end
    local beforeVisual=CONFIG.mobileSlotVisual(b)
    local beforePreview=CONFIG.mobilePreviewWitness(unit)
    -- Avoid toggling an already active preview OFF. This was another repeated
    -- selection regression when the script's selectedPreview cache desynced.
    if beforePreview then
        log("MOBILE PREVIEW ALREADY ACTIVE #"..index.." | refusing to toggle same slot")
        return true,"preview already visible"
    end
    local hitNames={}
    pcall(function()
        local stack=pg:GetGuiObjectsAtPosition(math.floor(c.X),math.floor(c.Y))
        for i=1,math.min(7,#stack) do
            hitNames[#hitNames+1]=stack[i]:GetFullName()
        end
    end)
    log("MOBILE SLOT HITTEST #"..index.." | "..table.concat(hitNames," > "))
    -- Real handler lookup: a game may listen on another GuiButton inside
    -- Troop1, not necessarily the generic InteractiveButton itself.
    local signals={}
    local function candidate(obj,sigName,rank)
        local ok,sig=pcall(function() return obj[sigName] end)
        if not ok or not sig then return end
        local n=-1
        if type(getconnections)=="function" then
            local success,connections=pcall(getconnections,sig)
            if success and type(connections)=="table" then n=#connections end
        end
        signals[#signals+1]={obj=obj,event=sigName,signal=sig,count=n,rank=rank}
    end
    candidate(b,"Activated",1)
    candidate(b,"MouseButton1Click",2)
    candidate(b,"MouseButton1Down",3)
    if b.Parent then
        for _,obj in ipairs(b.Parent:GetDescendants()) do
            if obj:IsA("GuiButton") and obj~=b then
                candidate(obj,"Activated",4)
                candidate(obj,"MouseButton1Click",5)
            end
        end
    end
    table.sort(signals,function(a,z)
        if a.count~=z.count then return a.count>z.count end
        return a.rank<z.rank
    end)
    local counts={pressed=0,clicked=0,activated=0}
    local probes={}
    local function probe(sig,key)
        local ok,conn=pcall(function()
            return sig:Connect(function() counts[key]=counts[key]+1 end)
        end)
        if ok and conn then probes[#probes+1]=conn end
    end
    probe(b.Activated,"activated")
    probe(b.MouseButton1Click,"clicked")
    probe(b.MouseButton1Down,"pressed")
    local function cleanup()
        for _,conn in ipairs(probes) do pcall(function() conn:Disconnect() end) end
    end
    -- Rotate INPUT METHODS between SEPARATE attempts. Do not touch the same
    -- slot twice inside one call: a working first activation toggles off.
    local n=(CONFIG.mobileEquipTries[unit] or 0)+1
    CONFIG.mobileEquipTries[unit]=n
    local chosen=nil
    local methods={"SIGNAL","TOUCH","VIM","SIGNAL_ALT"}
    local wanted=methods[(n-1)%#methods+1]
    -- v26: first Chef #5 proved that the actual game slot handler responds
    -- to InteractiveButton.Activated. Rotating to TOUCH/VIM for #9 onward
    -- failed to equip any preview, then poisoned the selection cache.
    -- Reuse the SAME observed-working route for subsequent Chef placements.
    if unit=="chef_tv_man" then
        wanted="SIGNAL"
        log("MOBILE CHEF SIGNAL REUSE #"..index
            .." | call="..n.." | using first successful Activated route")
    end
    if wanted=="SIGNAL" or wanted=="SIGNAL_ALT" then
        local opts={}
        for _,candidateInfo in ipairs(signals) do
            if candidateInfo.count>0 then opts[#opts+1]=candidateInfo end
        end
        -- If getconnections is not implemented by this Delta build, still
        -- allow ONE real callback attempt, but don't report it as confirmed.
        if #opts==0 and type(getconnections)~="function" then
            for _,entry in ipairs(signals) do
                if entry.obj==b and (entry.event=="Activated" or entry.event=="MouseButton1Click") then
                    opts[#opts+1]=entry
                end
            end
        end
        local entry=opts[(wanted=="SIGNAL_ALT" and 2 or 1)] or opts[1]
        if type(firesignal)=="function" and entry then
            local ok,err=pcall(function()
                if entry.event=="Activated" then
                    firesignal(entry.signal,nil,1)
                else
                    firesignal(entry.signal)
                end
            end)
            if ok then
                chosen="SIGNAL:"..entry.obj:GetFullName().."."..entry.event
            else
                log("MOBILE EQUIP SIGNAL ERROR #"..index.." | "..tostring(err))
            end
        end
        if not chosen then
            -- Use a single physical-style touch when the signal route is not
            -- supported; never try GUI and TOUCH back-to-back.
            wanted="TOUCH"
        end
    end
    if not chosen then
        local ok,why=tapWithMethod(c.X,c.Y,wanted)
        if not ok then
            cleanup()
            return false,"slot "..index.." "..wanted.." failed: "..tostring(why)
        end
        chosen=wanted
    end
    delayCheck(.24)
    local afterPreview,previewWhy=CONFIG.mobilePreviewWitness(unit)
    local changed=beforeVisual~=CONFIG.mobileSlotVisual(b)
    local eventCount=counts.activated+counts.clicked
    log("MOBILE SLOT ACTIVITY #"..index
        .." | route="..chosen.." | call="..n.." | buttonEvent="..eventCount
        .." pressed="..counts.pressed.." | UI_changed="..tostring(changed)
        .." | previewBefore="..tostring(beforePreview)
        .." previewAfter="..tostring(afterPreview))
    log("MOBILE PREVIEW EVIDENCE #"..index.." | "..previewWhy)
    cleanup()
    -- Existing preview Model is a positive signal. When a game draws its
    -- preview without an accessible Model, we cannot assert it was equipped;
    -- the native placement remains the ultimate proof (server-side model).
    if afterPreview then
        return true,"preview-model-visible via "..chosen
    end
    if eventCount>0 then
        return true,"button-event witnessed via "..chosen.."; preview unobservable"
    end
    if changed then
        return true,"slot visual changed via "..chosen.."; preview unobservable"
    end
    if chosen:sub(1,6)=="SIGNAL" then
        -- A callback was successfully invoked but neither visual nor preview
        -- is observable. The world placement will decide whether it worked.
        return true,"GUI callback sent (not proof of equip)"
    end
    -- If the executor delivered an input but the UI shows no response,
    -- continue to one cautious placement rather than falsely saying equipped.
    return true,"input sent without observable equip; see MOBILE SLOT ACTIVITY"
end
CONFIG.selectUnitForPreview=function(unit)
    if MOBILE_449 then
        -- No keyboard fallback on Android; it pretends selection succeeded
        -- even when no placement preview has been opened.
        return CONFIG.selectMobileUnit(unit)
    end
    local key=slots[unit]
    if not key then return false,"unit not mapped" end
    local ok,method=sendKey(key,true)
    if not ok then return false,method end
    if not delayCheck(.095) then return false,"stopped" end
    local off,err=sendKey(key,false)
    return off,off and method or err
end
local function restorePlacementPreview(unit,id)
    local target=slots[unit]
    local alternate=(target=="One") and "Two" or "One"
    local keepRotations=math.min(rotationsSinceSelection,8)
    log("PREVIEW RECOVERY #"..id.." | switch "..alternate.." -> "..target
        .." | R rotations="..keepRotations.." | focus="..tostring(windowFocused))
    local function pulse(key)
        local ok,method=sendKey(key,true)
        if not ok then return false,method end
        if not delayCheck(.095) then return false,"stopped" end
        local released,why=sendKey(key,false)
        if not released then return false,why end
        if not delayCheck(.20) then return false,"stopped" end
        return true,method
    end
    local reverse=({One="pumpkin_farmer",Two="chef_tv_man",Three="medic_cameraman"})
    local ok,why=CONFIG.selectUnitForPreview(reverse[alternate])
    if not ok then return false,"alternate slot: "..tostring(why) end
    delayCheck(.20)
    ok,why=CONFIG.selectUnitForPreview(unit)
    if not ok then return false,"target slot: "..tostring(why) end
    selectedPreview=unit
    -- Re-apply the R presses that the recorded run used for this preview.
    for _=1,keepRotations do
        ok,why=pulse("R")
        if not ok then return false,"rotation restore: "..tostring(why) end
    end
    log("PREVIEW RECOVERY #"..id.." | input sequence completed (not yet verified)")
    return true
end

CONFIG.cameraForPlacement=function(info,recT)
    cameraFrozen=recT
    -- The recording stores the exact CFrame used to project this world point.
    -- Applying it is more reliable than camera interpolation at sped-up times.
    cameraOverride=cframeFrom(info.cam)
    setCamera(recT,cameraOverride)
    task.wait(.14)
end
-- Final recovery: change only the CAMERA viewpoint (never the avatar) so the
-- screen-to-world placement ray can hit an unobstructed patch of ground.  The
-- strategy still requires a new model within 2 studs of the ORIGINAL point.
CONFIG.alternatePlacementCamera=function(info,recT,variant)
    local ground=Vector3.new(info.ground[1],info.ground[2],info.ground[3])
    local offsets={
        Vector3.new(0,30,8),
        Vector3.new(12,29,-6),
        Vector3.new(-11,31,-8),
        Vector3.new(6,34,12),
    }
    local offset=offsets[((variant-1)%#offsets)+1]
    local cf=CFrame.lookAt(ground+offset,ground)
    cameraFrozen=recT
    cameraOverride=cf
    setCamera(recT,cf)
    task.wait(.22)
    local x,y=project(ground)
    if not x then return nil,nil,"ground out of view from overhead camera" end
    return x,y,nil
end

-- v0.8.17: If the exact click is repeatedly rejected, first examine
-- a few candidate points CLOSE TO the recorded position. Existing towers can
-- overlap a new tower's placement footprint even when the camera ray hits ground.
-- Only visible, grounded, unoccupied candidates within the strict offset cap
-- may be clicked. This does not bypass game placement rules.
CONFIG.nearbySafePlacementPoints=function(info,goal)
    local folder=workspace:FindFirstChild("Troops")
    local existing={}
    if folder then
        for _,m in ipairs(folder:GetChildren()) do
            if m:IsA("Model") then
                local pos=modelPos(m)
                if pos then existing[#existing+1]=pos end
            end
        end
    end
    local rayParams=RaycastParams.new()
    rayParams.FilterType=Enum.RaycastFilterType.Exclude
    local excludes={}
    if folder then excludes[#excludes+1]=folder end
    if player.Character then excludes[#excludes+1]=player.Character end
    rayParams.FilterDescendantsInstances=excludes
    local candidates={}
    local radii={2.20,2.80,3.40}
    for _,radius in ipairs(radii) do
        for n=0,11 do
            local theta=n*math.pi/6
            local proposed=Vector3.new(goal.X+math.cos(theta)*radius,
                info.ground[2],goal.Z+math.sin(theta)*radius)
            local ok,hit=pcall(function()
                return workspace:Raycast(proposed+Vector3.new(0,70,0),Vector3.new(0,-145,0),rayParams)
            end)
            if ok and hit and math.abs(hit.Position.Y-info.ground[2])<1.65 then
                local point=hit.Position
                local drift=worldXZ(point,goal)
                if drift<=CONFIG.adaptiveMaxOffset then
                    local minSeparation=1000
                    for _,other in ipairs(existing) do
                        minSeparation=math.min(minSeparation,worldXZ(other,point))
                    end
                    if minSeparation>=CONFIG.adaptiveMinSeparation then
                        -- Prefer a clear point, but discourage large deviations.
                        candidates[#candidates+1]={pos=point,score=math.min(minSeparation,12)-drift*.38,
                            drift=drift,clearance=minSeparation}
                    end
                end
            end
        end
    end
    table.sort(candidates,function(a,b)
        return a.score>b.score
    end)
    local choices={}
    for _,item in ipairs(candidates) do
        local different=true
        for _,chosen in ipairs(choices) do
            if worldXZ(chosen.pos,item.pos)<1.1 then different=false; break end
        end
        if different then choices[#choices+1]=item end
        if #choices>=3 then break end
    end
    return choices
end

-- REDMI 449dp: recorded spot #1 is obstructed in the current match.
-- A camera ray reaching Y=2.4 is NOT proof there is room for a unit's base.
-- Find new, nearby, level ground with physical clearance before tapping.
CONFIG.mobileClearGroundCandidates=function(info,originalGoal,id)
    local groundY=info.ground[2]
    local rayParams=RaycastParams.new()
    rayParams.FilterType=Enum.RaycastFilterType.Exclude
    local overlapParams=OverlapParams.new()
    overlapParams.FilterType=Enum.RaycastFilterType.Exclude
    overlapParams.MaxParts=100
    local ignored={}
    if player.Character then ignored[#ignored+1]=player.Character end
    local troopFolder=workspace:FindFirstChild("Troops")
    if troopFolder then ignored[#ignored+1]=troopFolder end
    rayParams.FilterDescendantsInstances=ignored
    overlapParams.FilterDescendantsInstances=ignored
    local function check(x,z)
        local origin=Vector3.new(x,groundY+42,z)
        local ok,hit=pcall(function()
            return workspace:Raycast(origin,Vector3.new(0,-85,0),rayParams)
        end)
        if not ok or not hit then return nil,"no ground" end
        if hit.Normal.Y<.84 or math.abs(hit.Position.Y-groundY)>.85 then
            return nil,"raised/sloping surface: "..hit.Instance.Name
        end
        local p=hit.Position
        -- Check the physical footprint ABOVE the floor, not only the central ray.
        local partsOk,parts=pcall(function()
            return workspace:GetPartBoundsInBox(
                CFrame.new(p.X,p.Y+2.55,p.Z),Vector3.new(3.6,4.8,3.6),overlapParams)
        end)
        if not partsOk then return nil,"overlap query unavailable" end
        for _,part in ipairs(parts) do
            if part:IsA("BasePart") then
                local top=part.Position.Y+part.Size.Y*.5
                -- The map's own floor is allowed; decorations, walls and
                -- invisible collidable blockers protruding above are not.
                if top>p.Y+.65 and (part.CanCollide or part.Transparency<.96) then
                    return nil,"obstacle: "..part.Name
                end
            end
        end
        -- Avoid future recorded troop footprints and already-placed troops.
        for otherId,other in pairs(data.places) do
            if tonumber(otherId)~=id then
                local at=Vector3.new(other.pos[1],other.pos[2],other.pos[3])
                if worldXZ(at,p)<3.5 then return nil,"near another planned troop" end
            end
        end
        if troopFolder then
            for _,model in ipairs(troopFolder:GetChildren()) do
                if model:IsA("Model") then
                    local pos=modelPos(model)
                    if pos and worldXZ(pos,p)<4.25 then
                        return nil,"occupied by troop"
                    end
                end
            end
        end
        return p,nil
    end
    -- Do not retry the original point for #1: user confirmed obstacle there.
    local originalPoint,why=check(originalGoal.X,originalGoal.Z)
    log("MOBILE OBSTACLE CHECK #"..id.." | recorded="
        ..(originalPoint and "geometry clear (user reports red preview)" or tostring(why)))
    local candidates={}
    local rejects={}
    local radii={2.5,3.8,5.0,6.5,8.0,9.5,11.0}
    for _,radius in ipairs(radii) do
        for n=0,19 do
            local angle=n*math.pi/10
            local x=originalGoal.X+radius*math.cos(angle)
            local z=originalGoal.Z+radius*math.sin(angle)
            local pos,reason=check(x,z)
            if not pos then
                local category=tostring(reason):gsub(":.*$","")
                rejects[category]=(rejects[category] or 0)+1
            end
            if pos then
                local distinct=true
                for _,previous in ipairs(candidates) do
                    if worldXZ(previous.pos,pos)<3.0 then
                        distinct=false
                        break
                    end
                end
                if distinct then
                    candidates[#candidates+1]={pos=pos,offset=radius}
                    if #candidates>=30 then break end
                end
            end
        end
        if #candidates>=30 then break end
    end
    table.sort(candidates,function(a,b) return a.offset<b.offset end)
    local rejected={}
    for reason,num in pairs(rejects) do rejected[#rejected+1]={reason,num} end
    table.sort(rejected,function(a,b)return a[2]>b[2] end)
    local lines={}
    for j=1,math.min(#rejected,5) do lines[#lines+1]=rejected[j][1].."="..rejected[j][2] end
    log("MOBILE GROUND REJECTS #"..id.." | "..table.concat(lines,"; "))
    log("MOBILE FREE GROUND #"..id.." | candidates="..#candidates
        .." | original X="..string.format("%.2f",originalGoal.X)
        .." Z="..string.format("%.2f",originalGoal.Z))
    return candidates
end

-- When 140 surrounding geometry checks give ZERO choices, don't pretend a new
-- coordinate is safe. Ask for ONE visibly green point, detect the actual troop,
-- then save its coordinates for later matches on this device.
CONFIG.manualGreenPointForType=function(info,baselineAll,id)
    cameraFrozen=nil
    cameraOverride=nil
    unbindCamera() -- user needs free camera while finding a GREEN area
    collapseReplayMenu(true)
    local slot=({pumpkin_farmer=1,chef_tv_man=2,medic_cameraman=3})[info.unit] or "?"
    local label="unit #"..id.." ("..info.unit..")"
    say("ONE-TIME GREEN POINT #"..id,
        "Tap slot "..slot..", move RED preview onto GREEN ground, tap to place")
    warn("MOBILE GREEN MANUAL #"..id.." | Place ONE "..info.unit
        .." on a GREEN area within 120s; the position is saved for future matches")
    pcall(function()
        game:GetService("StarterGui"):SetCore("SendNotification",{
            Title="Legacy TTD: "..label,
            Text="Tap slot "..slot.." and place "..info.unit.." on GREEN ground (120 sec)",Duration=15})
    end)
    local deadline=os.clock()+120
    local nextUpdate=0
    while not stopped and os.clock()<deadline do
        local fresh={}
        for _,kind in ipairs({"pumpkin_farmer","chef_tv_man","medic_cameraman"}) do
            for _,m in ipairs(modelsFor(kind)) do
                if not baselineAll[m] and not claimedModel(m) then
                    fresh[#fresh+1]={kind=kind,model=m,pos=modelPos(m)}
                end
            end
        end
        if #fresh>1 then return false,"Manual calibration #"..id..": multiple new troops detected" end
        if #fresh==1 then
            local item=fresh[1]
            if item.kind~=info.unit then
                return false,"Manual calibration #"..id.." spawned "..item.kind
                    .." instead of "..info.unit
            end
            if item.pos then
                local p=item.pos
                local rayParams=RaycastParams.new()
                rayParams.FilterType=Enum.RaycastFilterType.Exclude
                local ignored={}
                local folder=workspace:FindFirstChild("Troops")
                if folder then ignored[#ignored+1]=folder end
                if player.Character then ignored[#ignored+1]=player.Character end
                rayParams.FilterDescendantsInstances=ignored
                local ray=workspace:Raycast(p+Vector3.new(0,35,0),Vector3.new(0,-90,0),rayParams)
                if not ray or ray.Normal.Y<.70 then
                    return false,"Manual "..info.unit.." placed, but its ground could not be verified"
                end
                info.pos={p.X,p.Y,p.Z}
                info.ground={ray.Position.X,ray.Position.Y,ray.Position.Z}
                placedModels[id]=item.model
                placedTimes[id]=os.clock()
                selectedPreview=nil
                rotationsSinceSelection=0
                local saved=saveGreenPoint(id,info)
                log(string.format("MOBILE GREEN POINT LEARNED #%d | %s | pos=(%.3f,%.3f,%.3f) ground=(%.3f,%.3f,%.3f) saved=%s",
                    id,info.unit,p.X,p.Y,p.Z,ray.Position.X,ray.Position.Y,ray.Position.Z,tostring(saved)))
                say("GREEN POINT CONFIRMED #"..id,info.unit.." placed; resuming replay")
                return true
            end
        end
        if os.clock()>nextUpdate then
            log("MOBILE WAIT GREEN POINT #"..id.." | "..info.unit
                .." | remaining="..math.floor(deadline-os.clock()).."s")
            nextUpdate=os.clock()+9
        end
        task.wait(.20)
    end
    return false,"Manual green-point calibration timed out; no "..info.unit.." spawned (#"..id..")"
end

CONFIG.aimAtNearbyPlacement=function(info,recT,candidate)
    local origin=Vector3.new(info.ground[1],info.ground[2],info.ground[3])
    -- High angled view shows a ground patch without moving the avatar.
    local cf=CFrame.lookAt(origin+Vector3.new(1,38,12),origin)
    cameraFrozen=recT
    cameraOverride=cf
    setCamera(recT,cf)
    task.wait(.20)
    local x,y=project(candidate.pos)
    if not x then return nil,nil,"candidate outside viewport" end
    local camera=workspace.CurrentCamera
    local ray=camera:ViewportPointToRay(x,y)
    local params=RaycastParams.new()
    params.FilterType=Enum.RaycastFilterType.Exclude
    local ignored={}
    local troops=workspace:FindFirstChild("Troops")
    if troops then ignored[#ignored+1]=troops end
    if player.Character then ignored[#ignored+1]=player.Character end
    params.FilterDescendantsInstances=ignored
    local ok,hit=pcall(function() return workspace:Raycast(ray.Origin,ray.Direction*300,params) end)
    if not ok or not hit or worldXZ(hit.Position,candidate.pos)>1.15 then
        return nil,nil,"camera ray not on candidate ground"
    end
    return x,y,nil
end

CONFIG.placementRayInfo=function(x,y,goal)
    local camera=workspace.CurrentCamera
    if not camera then return "no-camera" end
    local ray=camera:ViewportPointToRay(x,y)
    local params=RaycastParams.new()
    params.FilterType=Enum.RaycastFilterType.Exclude
    local ignored={}
    local troops=workspace:FindFirstChild("Troops")
    if troops then ignored[#ignored+1]=troops end
    if player.Character then ignored[#ignored+1]=player.Character end
    params.FilterDescendantsInstances=ignored
    local ok,result=pcall(function()
        return workspace:Raycast(ray.Origin,ray.Direction*700,params)
    end)
    if not ok then return "raycast-error:"..tostring(result) end
    if not result then return "no-surface-hit" end
    local p=result.Position
    return tostring(result.Instance and result.Instance.Name or "?")
        .."; ray-to-goal="..string.format("%.1f",worldXZ(p,goal)).." studs"
end

-- v0.8.17 WORLD-TARGET PICKER: the demonstration video places troops while
-- barely moving the camera. The actual server commands are not visible in that
-- video, so do NOT guess any remote names or fire unverified server events.
-- Instead, validate where a proposed mouse click really intersects the ground.
-- Only adjust a previously failed recorded click; keep the first original click.
CONFIG.rayTargetScore=function(x,y,ground)
    local camera=workspace.CurrentCamera
    if not camera then return nil end
    local viewport=camera.ViewportSize
    if x<32 or y<32 or x>viewport.X-32 or y>viewport.Y-32 then return nil end
    local ray=camera:ViewportPointToRay(x,y)
    local params=RaycastParams.new()
    params.FilterType=Enum.RaycastFilterType.Exclude
    local ignores={}
    local troops=workspace:FindFirstChild("Troops")
    if troops then ignores[#ignores+1]=troops end
    if player.Character then ignores[#ignores+1]=player.Character end
    params.FilterDescendantsInstances=ignores
    local ok,hit=pcall(function()
        return workspace:Raycast(ray.Origin,ray.Direction*700,params)
    end)
    if not ok or not hit then return nil end
    -- Walls and roofs must never be substituted for playable ground.
    if hit.Normal.Y<.70 or math.abs(hit.Position.Y-ground.Y)>2.1 then return nil end
    return worldXZ(hit.Position,ground)
end

-- Redmi / Delta native first-of-type calibration: 1920x1080 cursor pixels
-- can land on a different world point on Android even when scaled correctly.
-- Aim the camera at the RECORDED GROUND coordinate, then derive a fresh
-- viewport pixel from that camera and reject clicks whose ray hits elsewhere.
-- This does not modify recorded world positions or any direct-place request.
-- v11: the previous build forcibly used click=viewport CENTER on every native
-- placement, even when the original camera and mouse target differed.  This
-- can hit a visible obstacle instead of the playable ground on Android.
-- Prefer the SAME recorded camera view and a world-projected target.  Every
-- candidate is checked against the actual FIRST ray hit, INCLUDING height.
CONFIG.mobileWorldPointAim=function(info,recT,attempt)
    local ground=Vector3.new(info.ground[1],info.ground[2],info.ground[3])
    local choices={
        -- v13: place the requested ground near the exact viewport center.
        -- v12's RECORDED camera sometimes projected at Y=416 (over the
        -- bottom Android GUI). A verified ray did NOT predict where the
        -- game's real placement handler spawned the troop.
        {name="CENTERED",cf=CFrame.lookAt(ground+Vector3.new(0,39,13),ground)},
        {name="OBLIQUE_A",cf=CFrame.lookAt(ground+Vector3.new(-13,30,13),ground)},
        {name="OBLIQUE_B",cf=CFrame.lookAt(ground+Vector3.new(14,34,-12),ground)},
        {name="RECORDED",cf=cframeFrom(info.cam)},
    }
    -- v23: Chef #9+ needs the same recorded-camera priority as #5.
    -- A different camera is allowed ONLY to aim at the SAME world spot.
    if info.unit=="chef_tv_man" then
        choices={
            {name="CHEF_RECORDED_CAMERA",cf=cframeFrom(info.cam)},
            {name="CHEF_SAME_WORLD_CENTER",cf=CFrame.lookAt(ground+Vector3.new(0,39,13),ground)},
        }
    end
    -- Rotate the fallback angle on retries, without changing the target in
    -- the middle of a synthetic touch gesture.
    if (attempt or 1)%2==0 and info~=data.places["5"] then
        choices[2],choices[3]=choices[3],choices[2]
    end
    local camera=workspace.CurrentCamera
    local rayParams=RaycastParams.new()
    rayParams.FilterType=Enum.RaycastFilterType.Exclude
    local ignored={}
    local troops=workspace:FindFirstChild("Troops")
    if troops then ignored[#ignored+1]=troops end
    if player.Character then ignored[#ignored+1]=player.Character end
    rayParams.FilterDescendantsInstances=ignored
    for _,choice in ipairs(choices) do
        if choice.cf then
            cameraFrozen=recT
            cameraOverride=choice.cf
            setCamera(recT,choice.cf)
            task.wait(.18)
            local x,y=project(ground)
            if x and y and camera then
                local ray=camera:ViewportPointToRay(x,y)
                local ok,hit=pcall(function()
                    return workspace:Raycast(ray.Origin,ray.Direction*650,rayParams)
                end)
                if ok and hit then
                    local drift=worldXZ(hit.Position,ground)
                    local height=hit.Position.Y-ground.Y
                    local accepted=drift<=0.50 and math.abs(height)<=0.38 and hit.Normal.Y>=0.79
                    log(string.format("MOBILE AIM SURFACE | view=%s | hit=%s | xz=%.2f dy=%.2f ny=%.2f | @%d,%d | %s",
                        choice.name,hit.Instance.Name,drift,height,hit.Normal.Y,x,y,
                        accepted and "GROUND_OK" or "REJECT"))
                    if accepted then
                        log(string.format("MOBILE WORLD AIM | click=%d,%d | ground X=%.3f Z=%.3f | rayDrift=%.3f | try=%d | camera=%s",
                            x,y,ground.X,ground.Z,drift,attempt or 1,choice.name))
                        return x,y,nil
                    end
                else
                    log("MOBILE AIM SURFACE | view="..choice.name.." | ray=no-hit")
                end
            else
                log("MOBILE AIM SURFACE | view="..choice.name.." | ground outside viewport")
            end
        end
    end
    return nil,nil,"All views intercepted by obstacles / elevated surface; no safe screen-space click"
end

-- v13: the slot is already confirmed in the user's v12 log:
-- Workspace.PlacingModels.PumpkinFarmer appeared after a SINGLE Activated.
-- In that same match the camera ray at (204,416) hit (-50.333,-95.534),
-- but the real troop spawned at (-47.912,-95.714). Therefore a CAMERA RAY
-- is NOT a trustworthy witness for where Android's VIM click places troops.
-- Move the synthetic cursor WITHOUT pressing and measure the REAL placing
-- preview. A local two-axis probe determines how the preview responds to
-- 2D cursor movement. Only click once a preview is close to the world goal.
CONFIG.mobileGhostModel=function(unit)
    local folder=workspace:FindFirstChild("PlacingModels")
    if not folder then return nil,"Workspace.PlacingModels missing" end
    local expected=norm(modelNames[unit] or unit)
    for _,m in ipairs(folder:GetDescendants()) do
        if m:IsA("Model") and norm(m.Name)==expected then
            return m,m:GetFullName()
        end
    end
    return nil,"PlacingModels lacks "..tostring(modelNames[unit] or unit)
end
CONFIG.lateChefPreviewVisual=function()
    local model=CONFIG.mobileGhostModel("chef_tv_man")
    if not model then return "no ghost" end
    local hints={}
    local red,green,total=0,0,0
    for _,part in ipairs(model:GetDescendants()) do
        if part:IsA("Highlight") then
            hints[#hints+1]="Highlight="..tostring(part.FillColor)
        elseif part:IsA("SelectionBox") then
            hints[#hints+1]="SelectionBox="..tostring(part.Color3)
        elseif part:IsA("BasePart") then
            total=total+1
            local c=part.Color
            if c.R>c.G*1.4 and c.R>c.B*1.4 then red=red+1 end
            if c.G>c.R*1.4 and c.G>c.B*1.4 then green=green+1 end
        end
        if #hints>=5 then break end
    end
    hints[#hints+1]=string.format("redParts=%d greenParts=%d totalParts=%d",red,green,total)
    return table.concat(hints,"; ").." (colors NOT authoritative placement validity)"
end
CONFIG.mobileGhostCursorAlign=function(unit,goal,startX,startY,slotId)
    if not VIM then return nil,nil,"VIM missing" end
    local view=liveViewport()
    local ghost,reason=CONFIG.mobileGhostModel(unit)
    if not ghost then
        log("MOBILE GHOST MISSING #"..slotId.." | "..tostring(reason))
        return nil,nil,"placement preview missing; do not blind-click"
    end
    -- Keep away from the hotbar and top Android overlays. The first slot's
    -- center (361,369) is not part of the playable ground region.
    local left,right,top,bottom=60,view.X-60,60,view.Y-88
    local function cursor(x,y)
        x=math.clamp(math.floor(x+.5),left,right)
        y=math.clamp(math.floor(y+.5),top,bottom)
        local ok,err=pcall(function() VIM:SendMouseMoveEvent(x,y,game) end)
        if not ok then return nil,nil,nil,"move rejected: "..tostring(err) end
        if not delayCheck(.15) then return nil,nil,nil,"stopped" end
        if not ghost.Parent then return nil,nil,nil,"preview disappeared" end
        local p=modelPos(ghost)
        if not p then return nil,nil,nil,"preview pivot unavailable" end
        return x,y,p,nil
    end
    local x,y,p,err=cursor(startX,startY)
    if not p then return nil,nil,err end
    local initialDist=worldXZ(p,goal)
    log(string.format("MOBILE GHOST POS #%d | screen=%d,%d preview=(%.3f,%.3f) target=(%.3f,%.3f) drift=%.3f",
        slotId,x,y,p.X,p.Z,goal.X,goal.Z,initialDist))
    local precision=(slotId==5) and .65 or .90
    -- Chef #5 aims at the ORIGINAL recorded point, not a nearby green substitute.
    if initialDist<=precision then
        log(string.format("MOBILE GHOST ALIGNED #%d | screen=%d,%d | drift=%.3f | no correction",slotId,x,y,initialDist))
        return x,y,nil
    end
    local step=16
    -- Try independent cursor movements (no down/up). No troop is spawned.
    local x1,y1,px,ex=cursor(x+step,y)
    if not px then return nil,nil,"ghost X probe: "..tostring(ex) end
    local x2,y2,py,ey=cursor(x,y+step)
    if not py then return nil,nil,"ghost Y probe: "..tostring(ey) end
    local du=x1-x
    local dv=y2-y
    if du<2 or dv<2 then return nil,nil,"ghost probe blocked by screen edge" end
    local a,b=(px.X-p.X)/du,(py.X-p.X)/dv
    local c,d=(px.Z-p.Z)/du,(py.Z-p.Z)/dv
    local determinant=a*d-b*c
    log(string.format("MOBILE GHOST RESPONSE #%d | dX/px=(%.4f,%.4f) dZ/px=(%.4f,%.4f) det=%.5f",
        slotId,a,b,c,d,determinant))
    if math.abs(determinant)<.0002 then
        return nil,nil,"mouse movement does not control preview on this Android input route"
    end
    -- v27: Late Chef fallback has a very different camera perspective.
    -- For #12 the old unrestricted 85px Newton correction oscillated
    -- between 6.74 and 20.81 studs. Backtrack any correction that makes
    -- the real ghost farther away; never click just because a ray is valid.
    if unit=="chef_tv_man" and slotId>=9 then
        local previous=initialDist
        for iteration=1,6 do
            local dx,dz=goal.X-p.X,goal.Z-p.Z
            local shiftX=(dx*d-b*dz)/determinant
            local shiftY=(a*dz-dx*c)/determinant
            local chosen=nil
            for _,ratio in ipairs({1,.5,.25,.125}) do
                local sx=math.clamp(shiftX*ratio,-26,26)
                local sy=math.clamp(shiftY*ratio,-26,26)
                local nx=math.clamp(x+sx,left,right)
                local ny=math.clamp(y+sy,top,bottom)
                if math.abs(nx-x)>=1 or math.abs(ny-y)>=1 then
                    local xx,yy,pp,why=cursor(nx,ny)
                    if not pp then return nil,nil,"late chef probe: "..tostring(why) end
                    local dist=worldXZ(pp,goal)
                    log(string.format("CHEF SAFE AIM #%d | iter=%d ratio=%.3f pixel=%d,%d drift=%.3f",slotId,iteration,ratio,xx,yy,dist))
                    if dist<=precision then
                        log(string.format("MOBILE GHOST ALIGNED #%d | screen=%d,%d | drift=%.3f | safe correction",slotId,xx,yy,dist))
                        return xx,yy,nil
                    end
                    if dist+0.06<previous and (not chosen or dist<chosen.dist) then
                        chosen={x=xx,y=yy,p=pp,dist=dist}
                    end
                end
            end
            if not chosen then break end
            x,y,p,previous=chosen.x,chosen.y,chosen.p,chosen.dist
            -- Re-measure local pixel response at the accepted cursor.
            local bx,by,bp,why=cursor(x+12,y)
            if not bp then break end
            local cx,cy,cp,why2=cursor(x,y+12)
            if not cp then break end
            local du,dv=bx-x,cy-y
            if du<2 or dv<2 then break end
            a,b=(bp.X-p.X)/du,(cp.X-p.X)/dv
            c,d=(bp.Z-p.Z)/du,(cp.Z-p.Z)/dv
            determinant=a*d-b*c
            if math.abs(determinant)<.0002 then break end
        end
        return nil,nil,string.format("late Chef: verified ghost remains %.2f studs from recorded position; no blind click",previous)
    end
    -- Solve a local 2x2 map from screen-pixel movement to model X/Z.
    -- Re-observe the pivot after every correction, never trust the ray alone.
    local previous=initialDist
    for i=1,5 do
        local exx=goal.X-p.X
        local ezz=goal.Z-p.Z
        local shiftX=(exx*d-b*ezz)/determinant
        local shiftY=(a*ezz-exx*c)/determinant
        local nx=math.clamp(x+math.clamp(shiftX,-85,85),left,right)
        local ny=math.clamp(y+math.clamp(shiftY,-85,85),top,bottom)
        local newX,newY,newPos,why=cursor(nx,ny)
        if not newPos then return nil,nil,"ghost correction: "..tostring(why) end
        local dist=worldXZ(newPos,goal)
        log(string.format("MOBILE GHOST CORRECT #%d | step=%d pixel=%d,%d preview=(%.3f,%.3f) drift=%.3f",
            slotId,i,newX,newY,newPos.X,newPos.Z,dist))
        if dist<=precision then
            log(string.format("MOBILE GHOST ALIGNED #%d | screen=%d,%d | drift=%.3f | steps=%d",
                slotId,newX,newY,dist,i))
            return newX,newY,nil
        end
        if newX==x and newY==y then break end
        if dist>previous+1.5 and i>=2 then break end
        x,y,p=newX,newY,newPos
        previous=dist
    end
    return nil,nil,string.format("preview stayed %.2f studs from target after safe cursor corrections; no click",previous)
end

-- v11: old v5 rejected 140/140 points by mistaking decorative MeshParts for
-- collision blockers. This samples the ACTUAL surface height across a small
-- physical footprint and refuses to click when the first ray lands on a roof.
CONFIG.mobileGroundPatch=function(x,z,groundY)
    local params=RaycastParams.new()
    params.FilterType=Enum.RaycastFilterType.Exclude
    local ignore={}
    if player.Character then ignore[#ignore+1]=player.Character end
    local folder=workspace:FindFirstChild("Troops")
    if folder then ignore[#ignore+1]=folder end
    params.FilterDescendantsInstances=ignore
    local highestError=0
    local sampleName="?"
    local samples={{0,0},{.65,0},{-.65,0},{0,.65},{0,-.65}}
    for _,offset in ipairs(samples) do
        local px,pz=x+offset[1],z+offset[2]
        local ok,hit=pcall(function()
            return workspace:Raycast(Vector3.new(px,groundY+20,pz),Vector3.new(0,-32,0),params)
        end)
        if not ok or not hit then return nil,"surface missing" end
        if hit.Normal.Y<.78 then return nil,"wall / slope "..hit.Instance.Name end
        local err=math.abs(hit.Position.Y-groundY)
        highestError=math.max(highestError,err)
        if err>.42 then return nil,string.format("wrong-height %s (%.2f)",hit.Instance.Name,err) end
        if offset[1]==0 and offset[2]==0 then sampleName=hit.Instance.Name end
    end
    return Vector3.new(x,groundY,z),sampleName
end

CONFIG.mobileFarmerAutoTargets=function(info,id)
    if id==7 then
        local point=Vector3.new(info.ground[1],info.ground[2],info.ground[3])
        log(string.format("MOBILE MEDIC GREEN REUSE #7 | x=%.3f y=%.3f z=%.3f | saved=%s",
            point.X,point.Y,point.Z,tostring(savedGreenPoints[7])))
        return {{pos=point,offset=0,reason="CONFIRMED_MEDIC_GREEN",ground="user-confirmed location"}}
    end
    if id==5 then
        local record=Vector3.new(info.ground[1],info.ground[2],info.ground[3])
        log(string.format("CHEF RECORDING ONLY #5 | X=%.5f Y=%.5f Z=%.5f | no search / no auto relocation",
            record.X,record.Y,record.Z))
        return {{pos=record,offset=0,reason="RECORDED_EXACT",ground="original route"}}
    end
    local y=info.ground[2]
    local savedX,savedZ=info.pos[1],info.pos[3]
    -- These centers were actually used in successful user placements.
    -- Testing a DIFFERENT patch matters: v8-v10 repeatedly clicked the SAME
    -- red area six times while falsely announcing different attempts.
    local centers=(id==5) and {{savedX,savedZ}} or {
        {savedX,savedZ}, {-50.333,-95.534}, {-50.217,-95.055},
        {-49.81416,-95.0811},
    }
    local targets={}
    local seen={}
    local reasons={}
    local function add(x,z,label)
        local key=string.format("%.1f:%.1f",x,z)
        if seen[key] then return end
        seen[key]=true
        local p,why=CONFIG.mobileGroundPatch(x,z,y)
        if p then
            local duplicate=false
            for _,previous in ipairs(targets) do
                if worldXZ(previous.pos,p)<.48 then duplicate=true;break end
            end
            if not duplicate then
                targets[#targets+1]={pos=p,offset=worldXZ(p,Vector3.new(savedX,y,savedZ)),reason=label,ground=why}
            end
        else
            reasons[why]=(reasons[why] or 0)+1
        end
    end
    -- First try the actual previous green point. Then DIFFERENT nearby points
    -- selected from live map geometry, rather than infinite retries on red.
    for i=1,math.min(3,#centers) do add(centers[i][1],centers[i][2],"known-green-"..i) end
    for _,r in ipairs({2.35,4.5,1.55,6.0,.9,3.2}) do
        for _,i in ipairs({0,3,6,9,1,4,7,10,2,5,8,11}) do
            local theta=i*math.pi/6
            add(savedX+math.cos(theta)*r,savedZ+math.sin(theta)*r,"nearby-"..r)
        end
    end
    local diag={}
    for why,n in pairs(reasons) do diag[#diag+1]=tostring(why).."="..n end
    table.sort(diag)
    log("MOBILE TARGET SEARCH #"..tostring(id or 1).." | viable="..#targets.." | rejects="..table.concat(diag,"; "))
    -- Keep the original confirmed point first when the geometry says yes.
    -- The original recorded point can be blocked; it is never forced.
    return targets
end

CONFIG.correctedGroundClick=function(info,originalX,originalY)
    local ground=Vector3.new(info.ground[1],info.ground[2],info.ground[3])
    local px,py=project(ground)
    local choices={{originalX,originalY}}
    if px and py then choices[#choices+1]={px,py} end
    -- In the recorded run a tower sometimes appeared when clicking a few pixels
    -- away from the center; test a small local lattice, never a remote random spot.
    for _,off in ipairs({{5,0},{-5,0},{0,5},{0,-5},{5,5},{-5,5},{5,-5},{-5,-5},
        {9,0},{-9,0},{0,9},{0,-9}}) do
        choices[#choices+1]={originalX+off[1],originalY+off[2]}
    end
    local base=CONFIG.rayTargetScore(originalX,originalY,ground)
    local bestX,bestY,bestError=nil,nil,math.huge
    for _,q in ipairs(choices) do
        local errorValue=CONFIG.rayTargetScore(q[1],q[2],ground)
        if errorValue and errorValue<=CONFIG.worldRayMaxDrift then
            -- Prefer minimal world error, then a click close to the genuine recording.
            local score=errorValue+math.abs(q[1]-originalX)*.003
                +math.abs(q[2]-originalY)*.003
            if score<bestError then
                bestError=score
                bestX,bestY=q[1],q[2]
            end
        end
    end
    if not bestX then return nil,nil,base,"no clear ground ray close to recorded placement" end
    return bestX,bestY,base,bestError
end

-- ===== PER-SESSION BRIDGENET2 CALIBRATION =====
-- The same successful place had opcode W in an earlier client and j in this
-- client's context capture. BridgeNet2 generates compact ids; NEVER save them
-- to disk or assume j is correct for the next server.
-- Capture the ACTUAL outbound placement arguments, not just the first Pumpkin code.
-- The first troop of EACH type is placed natively so we learn its exact payload.
local sessionPlaceCode=nil
local sessionPlaceCaptured=0
local sessionHookReady=false
local sessionHookError=nil
local sessionPlaceProfiles={}
local observedPlaceCalls={}
local calibrationRotationPending=0
-- Direct upgrade discovery is SESSION-LOCAL. No guessed BridgeNet2 IDs.
local upgradeProfiles={}
local upgradeCapture=nil
local function payloadHasInstance(value,wanted,seen,depth)
    if typeof(value)=="Instance" then return value==wanted end
    if type(value)~="table" or depth>5 then return false end
    if seen[value] then return false end
    seen[value]=true
    for k,v in pairs(value) do
        if payloadHasInstance(k,wanted,seen,depth+1)
            or payloadHasInstance(v,wanted,seen,depth+1) then return true end
    end
    return false
end
local function replaceUpgradeInstance(value,from,to,seen,depth)
    if typeof(value)=="Instance" then
        if value==from then return to,true end
        return value,false
    end
    if type(value)~="table" then return value,false end
    if depth>6 then return nil,false end
    if seen[value] then return seen[value],false end
    local t={}; seen[value]=t
    local replaced=false
    for k,v in pairs(value) do
        local nk,rk=replaceUpgradeInstance(k,from,to,seen,depth+1)
        local nv,rv=replaceUpgradeInstance(v,from,to,seen,depth+1)
        if nk==nil then return nil,false end
        t[nk]=nv;replaced=replaced or rk or rv
    end
    return t,replaced
end
local function learnUpgradeProfile(unit,level,cost,sourceModel,samples,id)
    local key=unit..":"..tostring(level)
    if upgradeProfiles[key] then return true end
    -- Only one model-addressed packet inside the confirmed-upgrade window
    -- is sufficiently unambiguous to use. Never guess a command name.
    local unique={}
    local found={}
    for _,entry in ipairs(samples) do
        local tag=entry[2]
        if type(tag)=="string" and not found[tag] then
            found[tag]=true
            unique[#unique+1]=entry
        end
    end
    if #unique~=1 or type(cost)~="number" or cost<=0 then
        say("DIRECT UPGRADE UNAVAILABLE", "#"..id.." "..key
            .." | total="..#samples.." unique codes="..#unique)
        return false
    end
    local entry=unique[1]
    upgradeProfiles[key]={payload=entry,source=sourceModel,cost=cost}
    say("DIRECT UPGRADE LEARNED",key.." | cost $"..tostring(cost).." | this server only")
    return true
end
local gameRemote=game:GetService("ReplicatedStorage"):FindFirstChild("dataRemoteEvent")
if type(hookmetamethod)=="function" and type(getnamecallmethod)=="function" then
    local oldNamecall
    local function onNamecall(self,...)
        if getnamecallmethod()=="FireServer" and typeof(self)=="Instance"
            and self.Name=="dataRemoteEvent" then
            local gameOrigin=true
            if type(checkcaller)=="function" then
                local ok,ours=pcall(checkcaller)
                if ok and ours then gameOrigin=false end
            end
            local payload=select(1,...)
            -- Capture the exact real-game packet created by a verified GUI
            -- upgrade, limited to the click window and the selected model.
            if upgradeCapture and typeof(payload)=="table"
                and type(payload[2])=="string"
                and payloadHasInstance(payload[1],upgradeCapture.model,{},0) then
                local samples=upgradeCapture.samples
                if #samples<10 then samples[#samples+1]=payload end
            end
            if gameOrigin then
                if typeof(payload)=="table" and typeof(payload[1])=="table"
                    and typeof(payload[1][1])=="string"
                    and typeof(payload[1][2])=="Vector3"
                    and typeof(payload[1][3])=="number"
                    and typeof(payload[2])=="string" then
                    sessionPlaceCaptured=sessionPlaceCaptured+1
                    observedPlaceCalls[#observedPlaceCalls+1]={
                        at=os.clock(), name=payload[1][1], pos=payload[1][2],
                        rotation=payload[1][3], code=payload[2]
                    }
                    if #observedPlaceCalls>40 then table.remove(observedPlaceCalls,1) end
                end
            end
        end
        return oldNamecall(self,...)
    end
    local fn=(type(newcclosure)=="function" and newcclosure(onNamecall)) or onNamecall
    local ok,previous=pcall(function() return hookmetamethod(game,"__namecall",fn) end)
    if ok and type(previous)=="function" then
        oldNamecall=previous
        sessionHookReady=true
    else
        sessionHookError="namecall hook failed: "..tostring(previous)
    end
else
    sessionHookError="hookmetamethod/getnamecallmethod unavailable in Volt"
end
CONFIG.calibrationStatus=function()
    return "observed calls="..tostring(sessionPlaceCaptured)
        .." hook="..tostring(sessionHookReady)
end
CONFIG.findObservedPlaceSince=function(startIndex,spawn)
    local pos=modelPos(spawn)
    if not pos then return nil end
    local nearest,best=nil,math.huge
    for i=startIndex+1,#observedPlaceCalls do
        local entry=observedPlaceCalls[i]
        local dx=entry.pos.X-pos.X
        local dz=entry.pos.Z-pos.Z
        local distance=math.sqrt(dx*dx+dz*dz)
        if distance<best then nearest,best=entry,distance end
    end
    if best>5 then return nil end
    return nearest,best
end
CONFIG.placementErrorText=function()
    for _,element in ipairs(pg:GetDescendants()) do
        if element:IsA("TextLabel") and vis(element) then
            local t=tostring(element.Text or "")
            if t:find("Error 002",1,true) or t:find("Error 00",1,true) then
                return t:sub(1,170)
            end
        end
    end
    return nil
end
CONFIG.directRemote=function()
    local rs=game:GetService("ReplicatedStorage")
    local remote=rs:FindFirstChild("dataRemoteEvent")
    if remote and remote:IsA("RemoteEvent") then return remote end
    return nil,"ReplicatedStorage.dataRemoteEvent (RemoteEvent) missing"
end
-- v23: when a later ChefTVMan DIRECT packet is rejected, use the same
-- server-confirmed GUI route that worked for #5, but NEVER move to a different
-- world target or click without a real, aligned PlacingModels preview.
local function isPreciseNativePlacement(id,info)
    return MOBILE_449 and (id==1 or id==5 or id==7
        or (id>=9 and info.unit=="chef_tv_man"))
end

local function doCalibrationPlacement(id,recT)
    collapseReplayMenu(true)
    local info=data.places[tostring(id)]
    if not info then return false,"unknown placement id "..tostring(id) end
    local preciseNative=isPreciseNativePlacement(id,info)
    if not workspace:FindFirstChild("Troops") then
        return false,"Workspace.Troops missing; start inside the match"
    end
    local goal=Vector3.new(info.pos[1],info.pos[2],info.pos[3])
    local ground=Vector3.new(info.ground[1],info.ground[2],info.ground[3])
    local baseline={}
    for _,m in ipairs(modelsFor(info.unit)) do baseline[m]=true end
    local baselineAll={}
    -- Include all recognized and other Models: a new model must not trigger
    -- repeated clicks just because its type or pivot differs from recording.
    local troopFolder=workspace:FindFirstChild("Troops")
    if troopFolder then
        for _,m in ipairs(troopFolder:GetChildren()) do
            if m:IsA("Model") then baselineAll[m]=true end
        end
    end
    local function confirmedPlacement(model,mode,x,y,dist)
        placedModels[id]=model
        placedTimes[id]=os.clock()
        if MOBILE_449 and (id==1 or id==7) then
            local pivot=modelPos(model)
            if pivot then
                info.pos={pivot.X,pivot.Y,pivot.Z}
                -- Native placement may legitimately snap 1-3 studs on Android.
                -- Keep ground XZ in sync with the server-confirmed pivot,
                -- otherwise next launch aims at the old ground with a NEW pos.
                info.ground={pivot.X,info.ground[2],pivot.Z}
                local saved=saveGreenPoint(id,info)
                log(string.format("MOBILE GREEN POINT VERIFIED #%d | %s | X=%.3f Z=%.3f saved=%s",
                    id,info.unit,pivot.X,pivot.Z,tostring(saved)))
            end
        end
        selectedPreview=nil
        rotationsSinceSelection=0
        if mode=="EXECUTOR" or mode=="VIM" or mode=="TOUCH" then preferredClickMode=mode end
        cameraFrozen=nil; cameraOverride=nil
        local difference=dist or (modelPos(model) and worldXZ(modelPos(model),goal)) or 0
        if difference>CONFIG.placementRadiusXZ then
            say("PLACED WITH OFFSET #"..id,info.unit
                .." | new model confirmed "..string.format("%.2f",difference).." studs away; NO MORE CLICKS")
        else
            say("PLACED CONFIRMED #"..id,info.unit.." via "..tostring(mode)
                ..(x and (" @"..x..","..y) or ""))
        end
        return true
    end
    -- In previous v0.8, replayed clicks could spawn before the p event.
    -- Only accept an unclaimed model within the recorded position tolerance.
    local preexisting,preWhy=matchingAtRecordedSpot(info,nil)
    if preexisting then
        placedModels[id]=preexisting
        placedTimes[id]=os.clock()
        selectedPreview=nil
        rotationsSinceSelection=0
        say("PLACED #"..id.." detected already",info.unit)
        cameraFrozen=nil; cameraOverride=nil
        return true
    end
    if preWhy then return false,preWhy end
    if MOBILE_449 then CONFIG.mobileHotbarReport() end
    local attempts=0
    local adaptivePoints=nil
    local lastCashLog=0
    local failures={}
    local originalGoal=goal
    local mobileClearPoints=nil
    while not stopped do
        -- Check every new model BEFORE accepting one near the target: this
        -- also catches a wrong-slot spawn or two simultaneous stray units.
        local fresh,freshIssue,freshDistance=freshPlacedTroop(baselineAll,info.unit,goal,id)
        if fresh then
            return confirmedPlacement(fresh,"SPAWN WATCH",nil,nil,freshDistance)
        end
        if freshIssue then
            log("PLACE SAFETY #"..id.." | "..freshIssue)
            return false,freshIssue
        end
        local found,issue=matchingAtRecordedSpot(info,baseline)
        if found then return confirmedPlacement(found,"EXACT SPOT",nil,nil,0) end
        if issue then return false,issue end
        local cost=CONFIG.placeCost[info.unit] or 0
        local cash=cashOnHud(nil)
        if CONFIG.placementWaitForCash and (cash==nil or cash<cost) then
            if os.clock()-lastCashLog>4 then
                local _,_,skipState=locateAutoSkip()
                say("WAIT CASH PLACE #"..id,info.unit.." "..(cash and ("$"..cash) or "CASH HUD UNKNOWN").."/$"..cost.." | Auto Skip "..tostring(skipState))
                lastCashLog=os.clock()
            end
            delayCheck(.35)
        else
            -- Only Medic may use manual green calibration; Chef #5 is LOCKED
            -- to the recording and must not be silently moved elsewhere.
            if MOBILE_449 and id==7 and not savedGreenPoints[id] then
                log("MOBILE TYPE FIRST POINT #"..id.." | "..info.unit
                    .." | no verified saved spot; requesting manual GREEN calibration")
                return CONFIG.manualGreenPointForType(info,baselineAll,id)
            end
            local maxAttempts=MOBILE_449 and ((id==1) and 10 or (preciseNative and 2 or math.min(CONFIG.placementAttempts,4))) or CONFIG.placementAttempts
            if attempts>=maxAttempts then
                if MOBILE_449 then
                    log("MOBILE 449dp DIAG | native attempts exhausted; distinct live ground targets tested. See MOBILE AIM SURFACE and MOBILE TARGET DISTINCT")
                end
                if MOBILE_449 and id==1 then
                    return false,"AUTO FIRST FARMER: tried distinct verified-ground targets near X="
                        ..string.format("%.3f",goal.X).." Z="..string.format("%.3f",goal.Z)
                        .." but no unit spawned. See MOBILE AIM SURFACE and MOBILE SLOT ACTIVITY for the exact rejection."
                end
                if MOBILE_449 and id==5 then
                    return false,"CHEF #5: no server-confirmed placement after distinct live-ground attempts; see MOBILE GHOST logs"
                end
                if MOBILE_449 and id==7 then
                    return CONFIG.manualGreenPointForType(info,baselineAll,id)
                end
                return false,"Placement #"..id.." not confirmed after "..attempts.." safe attempts; no repeat overhead spam. "..table.concat(failures," | ")
            end
            attempts=attempts+1
            -- Use REAL map geometry and distinct world targets. The old v10
            -- grouped attempts by 3, so its six input attempts were only two
            -- nearly identical positions and often the same red preview.
            if MOBILE_449 and (id==1 or id==5 or id==7) then
                if not mobileClearPoints then
                    mobileClearPoints=CONFIG.mobileFarmerAutoTargets(info,id)
                    if #mobileClearPoints==0 then
                        return false,"FIRST TYPE #"..id..": no level ground within 6 studs of confirmed green point; no blind clicks"
                    end
                end
                local candidateIndex=(id==5 or id==7) and 1 or attempts -- Medic uses only confirmed green target
                local choice=mobileClearPoints[candidateIndex]
                if not choice then
                    return false,"FIRST TYPE #"..id..": tested every geometrically valid target, none spawned a troop"
                end
                local originalYOffset=info.pos[2]-info.ground[2]
                ground=choice.pos
                goal=Vector3.new(ground.X,ground.Y+originalYOffset,ground.Z)
                if id~=5 then
                    info.ground={ground.X,ground.Y,ground.Z}
                    info.pos={goal.X,goal.Y,goal.Z}
                end
                log(string.format("MOBILE TARGET DISTINCT #%d | try=%d target=%d/%d kind=%s surface=%s X=%.3f Y=%.3f Z=%.3f",
                    id,attempts,candidateIndex,#mobileClearPoints,choice.reason,tostring(choice.ground),
                    ground.X,ground.Y,ground.Z))
            end
            beginAutoMouseInput()
            -- First two attempts use the exact recorded preview/click.  If both
            -- failed, rebuild preview selection independently of our bookkeeping.
            if (not (MOBILE_449 and (id==1 or id==5 or id==7)) and (attempts==3 or attempts==5 or attempts==7)) then
                if attempts==3 or attempts==4 then CONFIG.mobileHotbarReport() end
                local okPreview,whyPreview=restorePlacementPreview(info.unit,id)
                if not okPreview then
                    log("PREVIEW RECOVERY FAILED #"..id..": "..tostring(whyPreview))
                    endAutoMouseInput()
                    return false,"cannot restore preview: "..tostring(whyPreview)
                end
            end
            -- Keep shield suspended during the entire placement interaction.
            -- When it was only suspended around a click, GUI input often hit
            -- CatchAccidentalClicks instead of the actual map.
            CONFIG.cameraForPlacement(info,recT)
            -- Recorded number keys select the preview BEFORE R rotations. v0.8
            -- selected the SAME slot again here, toggling the preview OFF.
            local isLateChef=MOBILE_449 and info.unit=="chef_tv_man" and id>=9
            -- v26: the per-type selectedPreview cache is NOT proof of actual
            -- equipment. #9 had TOUCH previewAfter=false; #10 then skipped
            -- SELECT HOTBAR entirely because stale selectedPreview==chef.
            local equipWitness=false
            if isLateChef then
                equipWitness=select(1,CONFIG.mobilePreviewWitness(info.unit))
                if not equipWitness and selectedPreview==info.unit then
                    log("MOBILE CHEF STALE EQUIP CACHE #"..id
                        .." | cached chef selected, live ghost missing; reselecting")
                    selectedPreview=nil
                end
            end
            if selectedPreview~=info.unit then
                say("SELECT HOTBAR #"..id,info.unit)
                local okKey,method=CONFIG.selectUnitForPreview(info.unit)
                if not okKey then endAutoMouseInput(); return false,"cannot select slot: "..tostring(method) end
                selectedPreview=info.unit -- provisional, not verified until model spawns
                log("MOBILE EQUIP PROVISIONAL #"..id.." | "..tostring(method))
                rotationsSinceSelection=0
                delayCheck(.32)
            end
            if isLateChef then
                -- Never continue to R presses or world aim if the Chef hotbar
                -- did not actually put a model in Workspace.PlacingModels.
                -- If game enforces a copy limit, repeated clicks cannot fix it.
                local preview,why=CONFIG.mobilePreviewWitness(info.unit)
                if not preview then
                    delayCheck(.24) -- allow delayed local preview replication
                    preview,why=CONFIG.mobilePreviewWitness(info.unit)
                end
                if not preview then
                    selectedPreview=nil
                    local liveCount=#modelsFor(info.unit)
                    log("MOBILE CHEF EQUIP FAILED #"..id
                        .." | confirmed copies="..liveCount
                        .." | Activated did not create ghost | "..tostring(why))
                    endAutoMouseInput()
                    return false,"CHEF #"..id.." hotbar did not enable placement preview"
                        .."; current Chef copies="..liveCount
                        .."; possible game placement limit or rejected GUI selection"
                end
                log("MOBILE CHEF EQUIP VERIFIED #"..id.." | real ghost visible")
            end
            -- First native placement of each troop type: restore the recorded
            -- R rotation before the actual click. A previously skipped R event
            -- must not change the orientation of the server-calibration sample.
            if calibrationRotationPending>0 then
                local count=calibrationRotationPending
                for _=1,count do
                    local rDown,rErr=sendKey("R",true)
                    if not rDown then
                        endAutoMouseInput()
                        return false,"calibration R key down failed: "..tostring(rErr)
                    end
                    delayCheck(.085)
                    sendKey("R",false)
                    delayCheck(.10)
                    rotationsSinceSelection=rotationsSinceSelection+1
                end
                say("CALIBRATION ROTATION #"..id,"applied "..count.." R presses")
                calibrationRotationPending=0
            end
            -- On retries keep preview selected; sending the numeric key again
            -- can cancel it. Try both complete input pipelines instead.
            -- The original v0.8.3 successfully placed #1 at (947,483), i.e.
            -- the exact mouse click from the recording. Versions after adding
            -- Mouse Shield used ground projection (948,455), 28 px too high.
            -- Prioritize the genuine recorded mouse coordinates. Screen sizes
            -- are scaled by the original recording viewport.
            local savedX,savedY=scale(info.click[1],info.click[2])
            local projX,projY=project(ground)
            local x,y=savedX,savedY
            -- If the first touch is ignored, retry once with VIM mouse input;
            -- do not use Windows-only executor APIs on an Android device.
            local method=(MOBILE_449 and VIM)
                and (preciseNative and "VIM" or ((attempts%2==1) and "TOUCH" or "VIM"))
                or ((attempts%2==1) and "VIM" or "EXECUTOR")
            -- Unfocused Roblox cannot safely receive executor (OS) mouse input:
            -- tapRawWithMethod redirects EXECUTOR -> VIM in the background.
            -- Log the EFFECTIVE method to avoid misleading diagnostics.
            if CONFIG.backgroundMode and not windowFocused then method="VIM" end
            -- Only after the original click fails with BOTH methods, try an
            -- explicitly diagnosed alternative projection; don't guess clicks.
            if attempts==4 and projX and projY then
                x,y=projX,projY
            end
            -- On later attempts use a small screen-space adjustment around
            -- the genuine recorded click.  The world-position verification
            -- still requires the intended unit within 2 studs (no false success).
            if attempts==6 then x,y=savedX-8,savedY+6 end
            if attempts==7 then x,y=savedX+8,savedY-6 end
            -- Only when the recorded point and small pixel corrections all
            -- failed, search a few grounded NEARBY candidates. Never click
            -- farther than 3.55 studs from the recorded target.
            if attempts>=8 and CONFIG.adaptivePlacement and not (MOBILE_449 and (id==1 or id==5 or id==7)) then
                if not adaptivePoints then
                    adaptivePoints=CONFIG.nearbySafePlacementPoints(info,goal)
                    log("ADAPTIVE SEARCH #"..id.." | candidates="..#adaptivePoints
                        .." | maxOffset="..CONFIG.adaptiveMaxOffset.." studs")
                end
                local choice=adaptivePoints[attempts-7]
                if not choice then
                    endAutoMouseInput()
                    return false,"No additional safe ground within "..CONFIG.adaptiveMaxOffset
                        .." studs of placement #"..id.."; refusing random clicks"
                end
                -- Before trying a new point rebuild preview once, not after
                -- every click. A valid preview is essential for unit placement.
                if attempts==8 then
                    local okPreview,whyPreview=restorePlacementPreview(info.unit,id)
                    if not okPreview then
                        endAutoMouseInput()
                        return false,"Adaptive preview recovery failed: "..tostring(whyPreview)
                    end
                end
                local ax,ay,reason=CONFIG.aimAtNearbyPlacement(info,recT,choice)
                if not ax then
                    endAutoMouseInput()
                    return false,"Adaptive camera failed: "..tostring(reason)
                end
                x,y=ax,ay
                log(string.format("ADAPTIVE TARGET #%d | drift=%.2f studs | nearestOther=%.2f | x=%.2f z=%.2f | click=%d,%d",
                    id,choice.drift,choice.clearance,choice.pos.X,choice.pos.Z,x,y))
                log("ADAPTIVE RAY #"..id.." | "..placementRayInfo(x,y,choice.pos))
            end
            -- Use verified world ray as a recovery, not as a replacement for a
            -- proven first click. Keeping the first recorded click is critical
            -- for the initial farms and existing working positions.
            if CONFIG.worldRayCorrection and not (MOBILE_449 and (id==1 or id==5 or id==7)) and attempts>=3 and attempts<=7
                and (attempts==3 or attempts==5 or attempts==7) then
                local smartX,smartY,oldError,newError=CONFIG.correctedGroundClick(info,savedX,savedY)
                if smartX and type(newError)=="number" and
                    (not oldError or newError+0.12<oldError) then
                    x,y=smartX,smartY
                    log(string.format("WORLD TARGET #%d | click=%d,%d | ray-error=%.2f studs | old=%s",
                        id,x,y,newError,oldError and string.format("%.2f",oldError) or "none"))
                elseif attempts==3 then
                    log("WORLD TARGET #"..id.." | no safer correction; retaining recorded click")
                end
            end
            if MOBILE_449 then
                -- Always use ground-verified native calibration on Android;
                -- the previously recorded 16:9 click is not an authoritative
                -- mobile placement position, even if its projection looks close.
                local ax,ay,aimError=CONFIG.mobileWorldPointAim(info,recT,attempts)
                if not ax then
                    endAutoMouseInput()
                    return false,"MOBILE WORLD AIM #"..id.." FAILED: "..tostring(aimError)
                end
                x,y=ax,ay
                if preciseNative then
                    -- v23: observed-preview correction also protects Chef #9+ fallback.
                    -- v20: medic gets the same observed-preview correction as farmer/chef.
                    -- v12 proved selection is correct but its click landed
                    -- 2.43 studs from the target. Check the actual client
                    -- placing model before allowing any mouse-down event.
                    local gx,gy,ghostError=CONFIG.mobileGhostCursorAlign(info.unit,goal,x,y,id)
                    if not gx then
                        log("MOBILE GHOST ALIGN UNKNOWN #"..id.." | attempt="..attempts
                            .." | "..tostring(ghostError))
                        if info.unit=="chef_tv_man" or id==7 then
                            endAutoMouseInput()
                            if id==7 then
                                log("MOBILE MEDIC PREVIEW ALIGN FAILED #7 | "..tostring(ghostError).." | manual calibration backup")
                                return CONFIG.manualGreenPointForType(info,baselineAll,id)
                            end
                            return false,"CHEF #"..id..": preview not aligned with ORIGINAL recorded location; "
                                ..tostring(ghostError)..". Refusing wrong spot."
                        end
                        -- The user's v12 actually SPAWNED a valid first troop
                        -- via VIM; it stopped solely because the 1.50-stud
                        -- tolerance rejected a 2.43-stud safe snap.
                        -- If a REAL preview exists, allow ONE VIM mouse click
                        -- on the ground-verified candidate, accept only a
                        -- matching SERVER troop within 3 studs. Never click
                        -- when the preview vanished or a wrong unit is shown.
                        local present=CONFIG.mobileGhostModel(info.unit)
                        if present then
                            log("MOBILE GHOST SAFE FALLBACK #"..id.." | preview exists; one VIM click on verified surface; accepting only server-confirmed spawn")
                        else
                            log("MOBILE GHOST REJECT #"..id.." | no equipped preview; skipping click")
                            endAutoMouseInput()
                            x,y=nil,nil
                        end
                    else
                        x,y=gx,gy
                    end
                end
            end
            if x and y and attempts==1 then
                log("PLACE TARGET #"..id.." | RECORDED @"..savedX..","..savedY
                    .." | WORLD PROJECTED @"..tostring(projX)..","..tostring(projY)
                    .." | deltaY="..tostring(projY and (savedY-projY) or "n/a")
                    .." | FINAL @"..x..","..y)
            end
            if x and y then
            -- While our automation clicks, the protective GUI MUST be disabled
            -- and inactive; this is also true during cursor movement.
            if mouseShieldGui then mouseShieldGui.Enabled=false end
            if mouseShieldSurface then mouseShieldSurface.Active=false; mouseShieldSurface.Visible=false end
            say("PLACE #"..id.." ATTEMPT "..attempts,info.unit.." / "..method.." @"..x..","..y)
            log("PLACE INPUT GUARD | shield="..tostring(mouseShieldGui and mouseShieldGui.Enabled)
                .." | suspended="..tostring(mouseShieldSuspend).." | focus="..tostring(windowFocused))
            local chefLateCheck=MOBILE_449 and info.unit=="chef_tv_man" and id>=9
            local requestCountBefore=chefLateCheck and #observedPlaceCalls or nil
            if chefLateCheck then
                log("CHEF PLACEMENT VISUAL #"..id.." | "..CONFIG.lateChefPreviewVisual())
            end
            local clickOk,clickWhy=tapWithMethod(x,y,method)
            endAutoMouseInput()
            if not clickOk then
                failures[#failures+1]=method..": "..tostring(clickWhy)
                log("PLACE INPUT FAILURE #"..id..": "..tostring(clickWhy))
                delayCheck(.18)
            else
                local untilAt=os.clock()+CONFIG.placementConfirmWait
                while not stopped and os.clock()<untilAt do
                    local justSpawned,spawnSafetyError,spawnDist=freshPlacedTroop(baselineAll,info.unit,goal,id)
                    if justSpawned then
                        return confirmedPlacement(justSpawned,method,x,y,spawnDist)
                    end
                    if spawnSafetyError then
                        log("PLACE SAFETY #"..id.." | "..spawnSafetyError)
                        return false,spawnSafetyError
                    end
                    local spawned,spawnIssue=matchingAtRecordedSpot(info,baseline)
                    if spawned then
                        return confirmedPlacement(spawned,method,x,y,0)
                    end
                    if spawnIssue then return false,spawnIssue end
                    delayCheck(.13)
                end
                failures[#failures+1]=method.." clicked but no matching model appeared"
                if requestCountBefore then
                    local sentCount=#observedPlaceCalls-requestCountBefore
                    log("CHEF PLACE NETWORK #"..id.." | GUI/VIM click generated "..sentCount
                        .." observed placement request(s) | "..(sentCount==0
                        and "CLIENT DID NOT SUBMIT placement; check red ghost, collision, range or input"
                        or "CLIENT SUBMITTED; no server model spawned, likely server validation/rejection"))
                end
                log("PLACE #"..id.." input sent, no model detected near ("..goal.X..", "..goal.Z..")")
                -- Placement can be rejected if the avatar is too far away even
                -- though a Scriptable camera can view the target. Log distance
                -- without silently moving the avatar against the user's wishes.
                local root=getRoot()
                local dist=root and worldXZ(root.Position,goal)
                local screenReasons={}
                for _,v in ipairs(pg:GetDescendants()) do
                    if v:IsA("TextLabel") and vis(v) then
                        -- screenVisible is defined later in this file; vis is enough here.
                        local text=norm(txt(v))
                        if text:find("limit",1,true) or text:find("toofar",1,true)
                            or text:find("cannotplace",1,true) or text:find("maxunits",1,true)
                            or text:find("closer",1,true) or text:find("notenough",1,true) then
                            screenReasons[#screenReasons+1]=txt(v):sub(1,55)
                            if #screenReasons>=3 then break end
                        end
                    end
                end
                log("PLACE DIAG #"..id.." | existing "..info.unit.."="..#modelsFor(info.unit)
                    .." | avatar distance="..(dist and string.format("%.1f",dist) or "unknown")
                    .." studs | UI hints="..(#screenReasons>0 and table.concat(screenReasons,"; ") or "none"))
            end
            end -- v13: only send placement click after a real ghost alignment
        end
    end
    return false,"stopped"
end
-- Resolve a first placement without a GUI click only when the currently
-- loaded session's ClientIdentifiers data contains an UNAMBIGUOUS, semantically
-- named troop-placement identifier. No hardcoded code across servers, no
-- brute force, and no call if candidate names/codes are ambiguous.
CONFIG.discoverPlaceIdentifier=function()
    if type(getgc)~="function" then return nil,"getgc missing" end
    local ok,objects=pcall(function() return getgc(true) end)
    if not ok or type(objects)~="table" then
        ok,objects=pcall(getgc)
    end
    if not ok or type(objects)~="table" then return nil,"getgc not enumerable" end
    local found={}
    local count=0
    for _,obj in pairs(objects) do
        if type(obj)=="table" then
            count=count+1
            -- Most registry tables are tiny. Scan pairs only; don't call
            -- their methods or require any modules.
            pcall(function()
                local examined=0
                for key,value in pairs(obj) do
                    examined=examined+1
                    if examined>120 then break end
                    if type(key)=="string" and type(value)=="string" and #value==1 then
                        local n=key:lower():gsub("[^a-z]","")
                        local isPlace=n:find("place",1,true) or n:find("spawn",1,true)
                            or n:find("deploy",1,true)
                        local isTroop=n:find("troop",1,true) or n:find("unit",1,true)
                            or n:find("tower",1,true)
                        if isPlace and isTroop and #n>=9 and #n<=52 then
                            found[key.."="..value]={name=key,code=value}
                        end
                    end
                end
            end)
        end
    end
    local entries={}
    for _,entry in pairs(found) do entries[#entries+1]=entry end
    if #entries~=1 then
        return nil,"semantic registry candidates="..#entries.." tables="..count
    end
    return entries[1],"unique registry identifier "..entries[1].name
end

local function doPlacement(id,recT)
    collapseReplayMenu(true)
    local info=data.places[tostring(id)]
    if not info then return false,"unknown placement #"..tostring(id) end
    local folder=workspace:FindFirstChild("Troops")
    if not folder then return false,"Workspace.Troops missing" end
    local remote,remoteErr=CONFIG.directRemote()
    if not remote then return false,remoteErr end
    local unitType=info.unit
    local wantedModel=modelNames[unitType]
    if not wantedModel then return false,"unknown unit type "..tostring(unitType) end
    local goal=Vector3.new(info.pos[1],info.pos[2],info.pos[3])

    local function nativeCalibrate(reason,disableDirect)
        if not sessionHookReady then
            return false,"native calibration requires hook: "..tostring(sessionHookError)
        end
        say("NATIVE TYPE CALIBRATION #"..id,unitType.." | "..tostring(reason))
        local captureBefore=#observedPlaceCalls
        -- A native click is needed only when the troop type is uncalibrated
        -- or when a direct request is rejected. This reuses the previously
        -- successful recorded-camera placement routine.
        calibrationRotationPending=(directRotations[id] or 1)-1
        bindCamera()
        local ok,why=doCalibrationPlacement(id,recT)
        unbindCamera()
        calibrationRotationPending=0
        if not ok then return false,"native placement failed: "..tostring(why) end
        local model=placedModels[id]
        if not model then return false,"native click reported success but no model bound" end
        local captured,captureDrift=CONFIG.findObservedPlaceSince(captureBefore,model)
        if not captured then
            -- Never guess an opcode or troop name from the model name.
            return false,"native troop spawned but its BridgeNet2 payload was not captured"
        end
        local pivot=modelPos(model)
        local yDelta=pivot and (captured.pos.Y-pivot.Y) or 0
        if math.abs(yDelta)>2 then
            return false,"captured Y offset implausible: "..tostring(yDelta)
        end
        local expectedRotation=directRotations[id] or 1
        local rotationShift=(captured.rotation-expectedRotation)%4
        sessionPlaceProfiles[unitType]={
            code=captured.code, remoteName=captured.name,
            yDelta=yDelta, rotationShift=rotationShift,
            nativeOnly=(disableDirect==true),
        }
        if not sessionPlaceCode then sessionPlaceCode=captured.code end
        say("TYPE PROFILE LEARNED "..unitType,
            "code="..tostring(captured.code).." serverName="..tostring(captured.name)
            .." | deltaY="..string.format("%.3f",yDelta)
            .." rot="..tostring(captured.rotation)
            .." shift="..tostring(rotationShift)
            .." inputDrift="..string.format("%.2f",captureDrift or -1)
            .." | "..(disableDirect and "NATIVE ONLY" or "DIRECT NEXT"))
        return true
    end

    -- Never reuse the Pumpkin Farmer template blindly for Chef/Medic.
    local profile=sessionPlaceProfiles[unitType]
    if MOBILE_449 and id==1 and not profile then
        local entry,reason=CONFIG.discoverPlaceIdentifier()
        log("MOBILE FIRST REGISTRY | "..tostring(reason)
            .." | "..(entry and "resolved without manual placement" or "native input fallback"))
        if entry then
            local before={}
            for _,m in ipairs(folder:GetChildren()) do
                if m:IsA("Model") then before[m]=true end
            end
            local rotation=directRotations[id] or 1
            local placedPoint=Vector3.new(goal.X,goal.Y,goal.Z)
            local sent,sendErr=pcall(function()
                remote:FireServer({{wantedModel,placedPoint,rotation},entry.code})
            end)
            if sent then
                local untilAt=os.clock()+2.6
                while not stopped and os.clock()<untilAt do
                    local spawned,why,dist=freshPlacedTroop(before,unitType,goal,id)
                    if why then return false,"auto-first safety: "..tostring(why) end
                    if spawned then
                        placedModels[id]=spawned
                        placedTimes[id]=os.clock()
                        sessionPlaceProfiles[unitType]={
                            code=entry.code,remoteName=wantedModel,
                            yDelta=0,rotationShift=0,nativeOnly=false,
                        }
                        selectedPreview=nil
                        say("AUTO FIRST DIRECT VERIFIED #1",unitType
                            .." | code from current BridgeNet2 registry="..entry.name
                            .." | drift="..string.format("%.2f",dist or 0))
                        return true
                    end
                    delayCheck(.16)
                end
                log("MOBILE FIRST REGISTRY REJECTED | no model after ONE send; switching to native input")
            else
                log("MOBILE FIRST REGISTRY FAILED | "..tostring(sendErr))
            end
        end
    end
    if not profile then
        return nativeCalibrate("FIRST OF TYPE; learn actual name/Y/rotation/opcode",false)
    end
    if profile.nativeOnly then
        return false,"DIRECT profile for this type unavailable; no automatic fallback to old native placement"
    end

    local baselineAll={}
    for _,m in ipairs(folder:GetChildren()) do
        if m:IsA("Model") then baselineAll[m]=true end
    end
    local function accept(model,drift)
        placedModels[id]=model
        placedTimes[id]=os.clock()
        selectedPreview=nil
        rotationsSinceSelection=0
        say("DIRECT PLACED #"..id,wantedModel
            .." | drift="..string.format("%.2f",drift or 0).." studs")
        return true
    end
    local cashLogAt=0
    while not stopped do
        local found,issue,dist=freshPlacedTroop(baselineAll,unitType,goal,id)
        if issue then return false,"DIRECT PLACE SAFETY #"..id..": "..issue end
        if found then return accept(found,dist) end
        local money=cashOnHud(nil)
        local cost=CONFIG.placeCost[unitType]
        if cost and (money==nil or money<cost) then
            if os.clock()-cashLogAt>5 then
                say("WAIT CASH DIRECT #"..id,wantedModel.." "
                    ..(money and ("$"..money.."/$"..cost) or "money HUD not ready"))
                cashLogAt=os.clock()
            end
            delayCheck(.35)
        else
            local requestPoint=Vector3.new(goal.X,goal.Y+profile.yDelta,goal.Z)
            local rotation=((directRotations[id] or 1)-1+profile.rotationShift)%4+1
            say("DIRECT TYPE PLACE #"..id,
                string.format("type=%s sendName=%s code=%s xyz=(%.2f,%.3f,%.2f) rot=%d cash=%s",
                    unitType,profile.remoteName,profile.code,
                    requestPoint.X,requestPoint.Y,requestPoint.Z,rotation,tostring(money)))
            local ok,err=pcall(function()
                remote:FireServer({{profile.remoteName,requestPoint,rotation},profile.code})
            end)
            if not ok then return false,"direct FireServer failed: "..tostring(err) end
            local deadline=os.clock()+4.2
            while not stopped and os.clock()<deadline do
                local spawned,spawnErr,spawnDist=freshPlacedTroop(baselineAll,unitType,goal,id)
                if spawnErr then return false,"DIRECT PLACE SAFETY #"..id..": "..spawnErr end
                if spawned then return accept(spawned,spawnDist) end
                delayCheck(.18)
            end
            -- Do not repeat a rejected FireServer and spam Error 002.
            -- Allow late replication to finish before switching to native GUI.
            if not delayCheck(1.2) then return false,"stopped" end
            local late,lateErr,lateDist=freshPlacedTroop(baselineAll,unitType,goal,id)
            if lateErr then return false,"DIRECT PLACE SAFETY #"..id..": "..lateErr end
            if late then return accept(late,lateDist) end
            local rejection=CONFIG.placementErrorText()
            say("DIRECT REJECTED #"..id,
                "no new "..wantedModel.." model | "..tostring(rejection or "server did not spawn troop")
                .." | single recorded-position native fallback next")
            if unitType=="chef_tv_man" then
                local root=getRoot()
                local dist=root and worldXZ(root.Position,goal)
                log("MOBILE CHEF REJECTION DIAG #"..id
                    .." | live Chef copies="..#modelsFor("chef_tv_man")
                    .." | cash="..tostring(cashOnHud(nil))
                    .." | avatar distance="..(dist and string.format("%.1f",dist) or "unknown")
                    .." | reason="..tostring(rejection or "not exposed by game"))
            end
            -- A per-server opcode can be valid even when the game refuses one
            -- specific spot. Do not retry that rejected remote packet or reuse
            -- another server's code. For Chef #9+, do one bounded native
            -- calibration using its ORIGINAL recorded camera/position. Check
            -- the live preview's actual pivot before VIM mouse-down.
            if MOBILE_449 and unitType=="chef_tv_man" and id>=9 then
                say("DIRECT NATIVE FALLBACK #"..id,
                    "chef preview -> recorded position -> VIM (max 2 checked clicks)")
                local nativeOk,nativeWhy=nativeCalibrate(
                    "DIRECT rejected at recorded point; preview-aligned VIM fallback",false)
                if nativeOk then
                    say("DIRECT NATIVE RECOVERED #"..id,
                        "server-confirmed ChefTVMan placed at original recorded location")
                    return true
                end
                return false,"DIRECT rejected; RECORDED NATIVE fallback also failed for #"
                    ..id..": "..tostring(nativeWhy)
            end
            return false,"DIRECT type request rejected for "..unitType
                ..". Cannot safely force direct placement or reuse other session's code."
        end
    end
    return false,"stopped"
end
local function aimAndOpen(model,id,t)
    if not model or not model.Parent then return false,"placed unit disappeared" end
    local pos=modelPos(model)
    if not pos then return false,"missing model pivot" end
    local info=data.places[tostring(id)]
    if MOBILE_449 then
        -- v18: do not gate GUI clicks on mouse.Target or Raycast.
        -- On Delta Android the v17 hover cursor stayed on ground/trees even
        -- when the camera was aimed directly at ChefTVMan. It prevented ALL
        -- clicks. Restore the v15 gesture that the user's logs confirmed
        -- upgraded chef Lv1->2 and Lv2->3 successfully.
        -- A pre-existing farmer menu is NOT evidence of the right instance.
        local copies=modelsFor(info.unit)
        local unique=(#copies==1 and copies[1]==model)
        local lv=modelLevel(model)
        local existing=inspect(info.unit)
        if unique and existing and (not lv or existing.level==lv) then
            log("MOBILE INSPECT SINGLE REUSE #"..id
                .." | "..info.unit.." only one live model; menu Lv"..existing.level)
            return true,"single troop menu already correct"
        end
        if existing then
            log("MOBILE INSPECT FORCE RESELECT #"..id
                .." | old menu Lv"..existing.level
                .." | copies="..#copies.." (cannot assume same instance)")
        end
        -- v21: after #8 is placed, TWO ChefTVMan models coexist. The
        -- original uncorrected screen-centre VIM clicks for #5 missed both
        -- (three "InspectMenu is not open" failures in the user's v20 log).
        -- Use the already measured Android +39px correction, but ONLY for
        -- selecting chef #5 when multiple chefs exist. Keep the proven
        -- earlier single-chef path and medic path unchanged.
        local medicInspect=(id==7 and info.unit=="medic_cameraman")
        local chefMultiInspect=(id==5 and info.unit=="chef_tv_man" and #copies>1)
        local target=pos
        if not chefMultiInspect then
            pcall(function()
                local cf,size=model:GetBoundingBox()
                if size.Y>0 and size.Y<80 then target=cf.Position end
            end)
        else
            -- An upgraded chef's bounding box may include oversized VFX.
            -- Its recorded model pivot is a more reliable clickable body point.
            log("MOBILE CHEF MULTI TARGET #"..id
                .." | copies="..#copies
                ..string.format(" | pivot=(%.3f,%.3f,%.3f)",target.X,target.Y,target.Z))
        end
        -- Side-on X-axis cameras separate #5 from #8, which are only
        -- about nine studs apart along Z. No orbiting through random angles.
        local viewpoints=medicInspect and {
            Vector3.new(18,15,0),
            Vector3.new(-18,15,0),
            Vector3.new(18,21,-6),
            Vector3.new(-18,21,6),
        } or chefMultiInspect and {
            Vector3.new(17,12,0),
            Vector3.new(-17,12,0),
            Vector3.new(20,17,3),
            Vector3.new(-20,17,-3),
        } or {
            Vector3.new(8,16,12),
            Vector3.new(-10,13,8),
            Vector3.new(1,22,-12),
        }
        local lastReason="target InspectMenu was not opened"
        for attempt,offset in ipairs(viewpoints) do
            if stopped then return false,"stopped" end
            cameraFrozen=t
            cameraOverride=CFrame.lookAt(target+offset,target)
            setCamera(t,cameraOverride)
            task.wait(.18)
            local x,y=project(target)
            if x then
                -- On this 921x449 Android viewport VIM hits approximately
                -- 39px LEFT of the coordinates it receives. This offset
                -- is verified by farmer/chef placement and medic inspection.
                -- Apply only to medic or MULTI-chef #5, keeping existing
                -- successful single-chef and farmer GUI clicks unchanged.
                local method=((medicInspect or chefMultiInspect) and "VIM")
                    or (attempt==1 and "TOUCH" or "VIM")
                local clickX=x
                if medicInspect or chefMultiInspect then
                    local viewport=liveViewport()
                    local correction=math.floor(39*viewport.X/921+0.5)
                    clickX=math.floor(math.max(60,math.min(viewport.X-60,x+correction)))
                    local tag=chefMultiInspect and "MOBILE CHEF MULTI VIM OFFSET #"
                        or "MOBILE MEDIC VIM OFFSET #"
                    log(tag..id
                        .." | view="..attempt.." | projected="..x..","..y
                        .." | corrected="..clickX..","..y
                        .." | dx="..(clickX-x).." | target="..model:GetFullName())
                end
                -- The old v17 mouse.Target gate did not track VIM clicks
                -- correctly and suppressed every attempt. Here we ONLY
                -- reject a known hit on a DIFFERENT placed troop in a
                -- fresh raycast. A missing hit is inconclusive, so clicks
                -- are still allowed in that case.
                local safeClick=true
                if chefMultiInspect then
                    local folder=workspace:FindFirstChild("Troops")
                    local camera=workspace.CurrentCamera
                    if folder and camera then
                        local params=RaycastParams.new()
                        params.FilterType=Enum.RaycastFilterType.Include
                        params.FilterDescendantsInstances={folder}
                        local ray=camera:ViewportPointToRay(x,y)
                        local hit=workspace:Raycast(ray.Origin,ray.Direction*300,params)
                        if hit and not hit.Instance:IsDescendantOf(model) then
                            safeClick=false
                            log("MOBILE CHEF MULTI BLOCKED #"..id
                                .." | view="..attempt
                                .." | another troop="..hit.Instance:GetFullName())
                        else
                            log("MOBILE CHEF MULTI RAY #"..id
                                .." | view="..attempt
                                .." | hit="..(hit and hit.Instance:GetFullName() or "none; inconclusive")
                                .." | attempt allowed")
                        end
                    end
                end
                if safeClick then
                    log("MOBILE INSPECT CLICK #"..id
                        .." | view="..attempt.." @"..clickX..","..y
                        .." | method="..method.." | copies="..#copies)
                    local ok,why=tapWithMethod(clickX,y,method)
                    task.wait(.35)
                    local found,inspectWhy=inspect(info.unit)
                    local observed=modelLevel(model)
                    if found and (not observed or found.level==observed) then
                    -- With one model of this type, unit+level identify it.
                    -- With several identical farmers, a fresh click is still
                    -- required; the model-level readback after Upgrade remains
                    -- the authoritative confirmation of the actual instance.
                    log("MOBILE INSPECT OPEN #"..id
                        .." | method="..method.." | view="..attempt
                        .." | menu Lv"..found.level
                        .." | model Lv"..tostring(observed)
                        .." | unique="..tostring(unique))
                        return true,"fresh inspect menu and target level match"
                    end
                    if found and observed and found.level~=observed then
                        lastReason="wrong instance/menu Lv"..found.level
                            .." target Lv"..observed
                    else
                        lastReason=tostring(inspectWhy or why)
                    end
                    log("MOBILE INSPECT RETRY #"..id
                        .." | view="..attempt.." | "..lastReason)
                else
                    lastReason="screen point intersects another troop; changed camera view"
                end
            else
                lastReason="target model not visible at view "..attempt
            end
        end
        return false,"InspectMenu not confirmed after "..#viewpoints
            .." bounded attempts: "..lastReason
            .." (not evidence of sleeping unit)"
    end
    local anchor=data.anchors[tostring(id)]
    freeze(t)
    if anchor and anchor.cam then
        local cf=cframeFrom(anchor.cam)
        if cf then cameraOverride=cf; workspace.CurrentCamera.CFrame=cf end
    end
    task.wait(.07)
    local x,y=project(pos)
    if not x then
        local c=workspace.CurrentCamera
        cameraOverride=CFrame.lookAt(c.CFrame.Position,pos)
        c.CFrame=cameraOverride
        task.wait(.07)
        x,y=project(pos)
    end
    if not x then return false,"model is outside camera" end
    local ok,why=tap(x,y)
    if not ok then return false,tostring(why) end
    return true
end
local function findSignalButton(button)
    if not button then return nil end
    if type(firesignal)~="function" then return nil,"firesignal not available" end
    if type(getconnections)=="function" then
        local success,conns=pcall(getconnections,button.Activated)
        if success and type(conns)=="table" and #conns==0 then
            return nil,"Activated has no connections"
        end
    end
    return button
end
-- v25: validate model identity before direct upgrade and recorded position as part of an
-- upgrade confirmation, not merely its name and Level number. A stale menu
-- belonging to another copy may display the very same level.
local function verifyRecordedUpgradeInstance(id,info,model)
    if not model or not model.Parent or not unitMatches(model,info.unit) then
        return false,"target instance missing or its unit type changed"
    end
    local folder=workspace:FindFirstChild("Troops")
    if not folder or not model:IsDescendantOf(folder) then
        return false,"target instance is not in live Workspace.Troops"
    end
    local pivot=modelPos(model)
    if not pivot then return false,"target pivot unavailable" end
    local target=Vector3.new(info.pos[1],info.pos[2],info.pos[3])
    local distance=worldXZ(pivot,target)
    if distance>3.20 then
        return false,string.format("target model moved %.2f studs away from recorded #%d",distance,id)
    end
    return true
end

local function copyLevelsOfType(unit)
    local snapshot={}
    for _,other in ipairs(modelsFor(unit)) do
        snapshot[other]=modelLevel(other)
    end
    return snapshot
end

-- First verified GUI upgrade of a unit type+level learns the real packet.
-- Later same-type/same-level upgrades use that packet directly and verify level.
local function directVerifiedUpgrade(id,before,after,recT,info,m,profile)
    -- v25: helper is declared before this closure (Lua lexical scope).
    local verified,verifyWhy=verifyRecordedUpgradeInstance(id,info,m)
    if not verified then return false,"DIRECT UPGRADE WRONG INSTANCE: "..tostring(verifyWhy) end
    local current=modelLevel(m)
    if current and current~=before then
        return false,"direct upgrade precondition: model level="..current.." expected="..before
    end
    local cash=nil
    local t0=os.clock()
    while not stopped and os.clock()-t0<75 do
        cash=cashOnHud(nil)
        if cash and cash>=profile.cost then break end
        delayCheck(.3)
    end
    if stopped then return false,"stopped" end
    if not cash or cash<profile.cost then
        return false,"cash HUD unreadable or too little money for direct upgrade"
    end
    local packet,changed=replaceUpgradeInstance(profile.payload,profile.source,m,{},0)
    if not changed or not packet then
        return false,"captured upgrade packet did not contain the source model"
    end
    local remote,why=CONFIG.directRemote()
    if not remote then return false,why end
    local sent,err=pcall(function() remote:FireServer(packet) end)
    if not sent then return false,"direct upgrade failed: "..tostring(err) end
    say("DIRECT UPGRADE #"..id,info.unit.." Lv"..before.." -> "..after)
    local untilAt=os.clock()+4
    while not stopped and os.clock()<untilAt do
        local observed=modelLevel(m)
        if observed==after then
            local stillCorrect,identityProblem=verifyRecordedUpgradeInstance(id,info,m)
            if not stillCorrect then return false,"direct verification identity lost: "..tostring(identityProblem) end
            local pivot=modelPos(m)
            say("DIRECT UPGRADE VERIFIED #"..id,
                "model level="..after.." | instance="..m:GetFullName()
                ..string.format(" | x=%.2f z=%.2f",pivot.X,pivot.Z))
            return true
        elseif observed and observed~=before then
            return false,"direct upgrade produced unexpected model level="..observed
        end
        delayCheck(.15)
    end
    -- Some Troops models have no Level field. Select ONLY for readback;
    -- never click the old UpgradeButton as a fallback.
    local opened,openWhy=aimAndOpen(m,id,recT)
    if not opened then return false,"no level confirmation: "..tostring(openWhy) end
    local checkUntil=os.clock()+3
    while not stopped and os.clock()<checkUntil do
        local state=inspect(info.unit)
        if state and state.level==after then
            say("DIRECT UPGRADE VERIFIED #"..id,"InspectMenu readback="..after)
            return true
        end
        if state and state.level>after then
            return false,"direct upgrade over-leveled, got "..state.level
        end
        delayCheck(.2)
    end
    return false,"direct upgrade not confirmed; OLD GUI fallback intentionally disabled"
end
local function guardedUpgrade(id,before,after,recT)
    collapseReplayMenu(true)
    local info=data.places[tostring(id)]
    local m=placedModels[id]
    if not m or not m.Parent then return false,"unit #"..id.." missing" end
    local upgradeKey=info.unit..":"..tostring(before)
    local savedProfile=upgradeProfiles[upgradeKey]
    local identityOk,identityWhy=verifyRecordedUpgradeInstance(id,info,m)
    if not identityOk then return false,"UPGRADE IDENTITY #"..id..": "..tostring(identityWhy) end
    if CONFIG.directUpgrade and savedProfile then
        return directVerifiedUpgrade(id,before,after,recT,info,m,savedProfile)
    end
    -- Unseen unit type+level: one legitimate, verified GUI upgrade is used
    -- to learn the actual remote command. No hardcoded event/opcode guesses.
    -- v0.7: no per-unit recorded timing gate here. On reaching an upgrade action,
    -- select this specific unit and send Activated at the first affordable moment.
    -- Keep actions sequential: money / sleeping unit can delay but never skip a step.
    if stopped then return false,"stopped" end
    local lastLog,tries,signalAttempts=0,0,0
    local signalSentAt=nil
    local signalCost=nil
    local upgradeSamples={}
    local sameTypeBefore=copyLevelsOfType(info.unit)
    local lastCashObserved=nil
    local lastCashChange=os.clock()
    local cashStallReported=false
    local mismatchStarted=nil
    local mismatchRetries=0
    -- Force selection of the recorded *instance* before reading the GUI.
    -- A stale InspectMenu for a different copy must never be trusted.
    local opened,openWhy=aimAndOpen(m,id,recT)
    if not opened then
        return false,"cannot select exact target #"..id.." for upgrade: "..tostring(openWhy)
    end
    delayCheck(.25)
    say("UPGRADE PENDING #"..id,info.unit.." Lv"..before.." -> "..after.."; exact instance reselected")
    while not stopped do
        local state,why=inspect(info.unit)
        local observed=modelLevel(m)
        -- A stale or overlapping InspectMenu can upgrade another copy of the
        -- same unit type. Detect this immediately instead of reporting success
        -- or pressing Upgrade a second time.
        if signalSentAt and observed==before then
            for other,earlier in pairs(sameTypeBefore) do
                local now=other.Parent and modelLevel(other)
                if other~=m and type(earlier)=="number" and type(now)=="number"
                    and now>earlier then
                    log("UPGRADE WRONG COPY DETECTED #"..id
                        .." | other="..other:GetFullName()
                        .." | prior Lv"..earlier.." now Lv"..now)
                    return false,"WRONG COPY upgraded instead of #"..id
                        .."; disabled this unit's further upgrades for this round"
                end
            end
        end
        if observed and observed>after then return false,"unit level skipped target: model reads Lv"..observed end
        if observed and observed~=before and observed~=after then
            return false,"target model level mismatch: model Lv"..observed..", expected "..before
        end
        if observed==after and not signalSentAt then
            return false,"target model reached Lv"..after
                .." without this script confirming an upgrade signal; STOPPED to avoid losing unit identity"
        end
        if observed==after then
            if CONFIG.directUpgrade then
                if not learnUpgradeProfile(info.unit,before,signalCost,m,upgradeSamples,id) then
                    return false,"cannot learn verified direct upgrade from this GUI signal; no guessed opcode"
                end
            end
            local consistent,reason=verifyRecordedUpgradeInstance(id,info,m)
            if not consistent then return false,"UPGRADE RESULT WRONG INSTANCE: "..tostring(reason) end
            say("UPGRADE CONFIRMED #"..id,
                info.unit.." Lv"..before.." -> "..after
                .." | verified model="..m:GetFullName())
            cameraFrozen=nil
            cameraOverride=nil
            return true
        end
        if state and state.level==after and signalSentAt
            and (observed==after or (not observed and #modelsFor(info.unit)==1)) then
            if CONFIG.directUpgrade then
                if not learnUpgradeProfile(info.unit,before,signalCost,m,upgradeSamples,id) then
                    return false,"cannot learn verified direct upgrade from this GUI signal; no guessed opcode"
                end
            end
            say("UPGRADE CONFIRMED #"..id,info.unit.." Lv"..before.." -> "..after.." (InspectMenu)")
            cameraFrozen=nil
            cameraOverride=nil
            return true
        end
        if state and state.level>after then
            return false,"inspect menu level is beyond expected Level "..after.."; wrong model or recording mismatch"
        end
        if state and state.level==before then
            mismatchStarted=nil
            mismatchRetries=0
            local cash=cashOnHud(state.root)
            if cash~=nil then
                if cash~=lastCashObserved then
                    lastCashObserved=cash
                    lastCashChange=os.clock()
                    cashStallReported=false
                elseif cash<state.cost and not cashStallReported
                    and os.clock()-lastCashChange>=30 then
                    log("ECONOMY STALLED #"..id.." | money $"..cash.." / $"..state.cost
                        .." unchanged 30s; not skipping upgrade; checking match result")
                    cashStallReported=true
                end
            end
            if cash~=nil and cash>=state.cost then
                if not signalSentAt or os.clock()-signalSentAt>=CONFIG.afterSignalWait then
                    if signalAttempts>=CONFIG.maxUpgradeSignalAttempts then
                        return false,"Upgrade not confirmed after "..signalAttempts.." verified Activated attempts"
                    end
                    local button,reason=findSignalButton(state.button)
                    if not button then return false,reason end
                    signalAttempts=signalAttempts+1
                    signalCost=state.cost
                    -- Capture only calls emitted during the actual button click.
                    local active={model=m,samples={}}
                    upgradeCapture=active
                    local fired,err=pcall(function() firesignal(button.Activated,nil,1) end)
                    delayCheck(.20)
                    if upgradeCapture==active then upgradeCapture=nil end
                    for _,packet in ipairs(active.samples) do
                        upgradeSamples[#upgradeSamples+1]=packet
                    end
                    if not fired then return false,"firesignal failed: "..tostring(err) end
                    signalSentAt=os.clock()
                    say("ACTIVATED #"..id.." attempt "..signalAttempts,"waiting for actual Level increase")
                    delayCheck(.35)
                else delayCheck(.17) end
            else
                if os.clock()-lastLog>CONFIG.sleepLogSeconds then
                    say("WAIT UPGRADE MONEY #"..id,info.unit.." "..(cash and ("$"..cash.."/$"..state.cost) or "money unreadable"))
                    lastLog=os.clock()
                end
                delayCheck(.35)
            end
        elseif state and state.level~=before then
            -- v15 got stuck indefinitely here because aimAndOpen returned
            -- immediately when ANY farmer menu was open, even a different copy.
            -- The clicked menu can advance to Lv3 while the recorded model
            -- remains at Lv2. Re-select the actual model, not the unit type.
            if not mismatchStarted then mismatchStarted=os.clock() end
            mismatchRetries=mismatchRetries+1
            if os.clock()-lastLog>CONFIG.sleepLogSeconds or mismatchRetries==1 then
                say("UPGRADE INSTANCE MISMATCH #"..id,
                    "target model Lv"..tostring(observed)
                    .." | menu Lv"..state.level
                    .." | expected Lv"..before.." -> "..after
                    .." | reselecting exact model")
                lastLog=os.clock()
            end
            if mismatchRetries>8 or os.clock()-mismatchStarted>18 then
                return false,"Upgrade #"..id.." WRONG INSTANCE: target model Lv"
                    ..tostring(observed)..", menu Lv"..state.level
                    ..". Stopped to avoid upgrading another farmer again."
            end
            local reselected,reselectWhy=aimAndOpen(m,id,recT)
            if not reselected then
                log("UPGRADE RESELECT FAILED #"..id.." | "..tostring(reselectWhy))
            else
                log("UPGRADE RESELECTED #"..id.." | target model Lv"..tostring(modelLevel(m)))
            end
            delayCheck(CONFIG.selectRetrySeconds)
        else
            if os.clock()-lastLog>CONFIG.sleepLogSeconds then
                say("WAIT INSPECT MENU #"..id,info.unit.." | "..tostring(why).." | selection retry, sleep NOT confirmed")
                lastLog=os.clock()
            end
            local okSelect,selectWhy=aimAndOpen(m,id,recT)
            if not okSelect and os.clock()-lastLog>CONFIG.sleepLogSeconds then
                log("auto select: "..tostring(selectWhy))
            end
            delayCheck(CONFIG.selectRetrySeconds)
        end
    end
    return false,"stopped"
end

