    launchReplay=function(source)
        if running or destroyed then return end
        if isResultActive and isResultActive() then
            say("START BLOCKED", "Victory/results screen still visible; awaiting Play Again")
            return
        end
        autoArmed=false
        autoBtn.Text="AUTO: OFF - CLICK TO ARM"
        collapseReplayMenu(true)
        if compactStatus then compactStatus.Text="AFK • PLAYING" end
        awaitingResultTransition=false
        resultGoneAt=nil
        userStopped=false
        victoryStopRequested=false
        playAgainAttemptedForMatch=false
        log("LAUNCH from "..tostring(source or "MANUAL").." | v0.8.21 PER-TYPE CALIBRATION")
        task.spawn(function()
            local replaySkippedPlaces=0
            local replaySkippedUpgrades=0
            local successful,reason=pcall(function()
                stopped=false
                running=true
                updateMouseShield()
                placedModels={}
                placedTimes={}
                sessionPlaceProfiles={}
                sessionPlaceCode=nil
                upgradeCapture=nil
                for key in pairs(upgradeProfiles) do upgradeProfiles[key]=nil end
                observedPlaceCalls={}
                sessionPlaceCaptured=0
                keyEventCount=0
                keysHeld={}
                paused=0
                cameraFrozen=nil
                cameraOverride=nil
                cameraTimeline=0
                camMoveFrom=0
                camMoveTo=0
                camMoveWallStart=0
                camMoveDuration=0
                mouseHeld={}
                selectedPreview=nil
                rotationsSinceSelection=0
                preferredClickMode=(MOBILE_449 and VIM) and "TOUCH" or "VIM"
                skippedMovement=0
                skippedRecordedMouse=0
                autoSkipHandled=false
                -- Release any stale movement key from an earlier executor run.
                for _,key in ipairs({"W","A","S","D","Space"}) do
                    pcall(function()
                        if type(keyrelease)=="function" and vkCodes[key] then keyrelease(vkCodes[key]) end
                        if VIM then VIM:SendKeyEvent(false,Enum.KeyCode[key],false,game) end
                    end)
                end
                local humanoid=player.Character and player.Character:FindFirstChildOfClass("Humanoid")
                if humanoid then pcall(function() humanoid:Move(Vector3.zero,false) end) end
                activeStart=os.clock()
                -- First troop is placed by the real GUI to learn this server's compact bridge code.
                -- Later troops use the learned code, camera stays still between GUI upgrades.
                say("PLAYING v0.8.21 MOBILE v26",#data.actions.." actions; first of EACH TYPE uses native click; others direct; LEARNED DIRECT upgrades")
                local prevRecordedTime=0
                local failedPlacements={}
                local disabledUpgradeIds={}
                local confirmedPlacementCount=0
                local confirmedUpgradeCount=0
                local skippedPlacementCount=0
                local skippedUpgradeCount=0
                for i,ev in ipairs(data.actions) do
                    if stopped then break end
                    local t=ev[1]
                    local typ=ev[2]
                    -- IMPORTANT: recorded timestamps are *ordering hints*, not hard delays.
                    -- Preserve key/button hold durations, but compress idle intervals.
                    -- Every placement/upgrade below remains a blocking verified operation.
                    local recordedGap=math.max(0,t-prevRecordedTime)
                    local anyMovement=keysHeld.W or keysHeld.A or keysHeld.S or keysHeld.D
                    local anyMouseDown=mouseHeld[0] or mouseHeld[1]
                    local waitFor=recordedGap
                    if CONFIG.instantNextAction and not anyMovement and not anyMouseDown then
                        waitFor=math.min(recordedGap,CONFIG.fastIdleMaxWait)
                    end
                    camMoveFrom=prevRecordedTime
                    camMoveTo=t
                    camMoveWallStart=os.clock()
                    camMoveDuration=waitFor
                    if waitFor>0 then delayCheck(waitFor) end
                    cameraTimeline=t
                    camMoveDuration=0
                    prevRecordedTime=t
                    if recordedGap>waitFor+2 and (typ=="u" or typ=="p") then
                        log(string.format("FAST FORWARD %.2fs idle -> %.2fs | next %s at recorded %.2f",recordedGap,waitFor,typ,t))
                    end
                    if stopped then break end
                    if typ=="k" then
                        local key=ev[3]
                        local down=(ev[4]==1)
                        local avatarKeys={W=true,A=true,S=true,D=true,Space=true,
                            LeftShift=true,RightShift=true,LeftControl=true,RightControl=true}
                        if avatarKeys[key] then
                            -- Avatar remains stationary. Camera follows recorded
                            -- WORLD positions rather than the character's movement.
                            skippedMovement=skippedMovement+1
                            if down then log("STATIONARY: skipped movement "..key) end
                        elseif MOBILE_449 and key=="R" and sessionPlaceCode then
                            -- v27: old replay discarded all late recorded R presses.
                            -- Only send rotation while a real Chef preview is active.
                            -- Direct placement already sends the saved rotation in its packet.
                            local ghost=CONFIG.mobileGhostModel("chef_tv_man")
                            if ghost then
                                local beforeDirection=nil
                                if down then
                                    local ok,cf=pcall(function() return ghost:GetPivot() end)
                                    if ok and cf then beforeDirection=cf.LookVector end
                                    CONFIG.lastChefRotateLook=beforeDirection
                                end
                                local ok,why
                                if VIM then
                                    ok,why=pcall(function() VIM:SendKeyEvent(down,Enum.KeyCode.R,false,game) end)
                                    if ok then why="VIM" end
                                else
                                    ok,why=sendKey("R",down)
                                end
                                if down then
                                    log("CHEF ROTATE R DOWN | delivered="..tostring(ok).." | route="..tostring(why))
                                else
                                    delayCheck(.10)
                                    local old=CONFIG.lastChefRotateLook
                                    local nowOk,nowCF=pcall(function() return ghost:GetPivot() end)
                                    local new=nowOk and nowCF and nowCF.LookVector
                                    local changed=(old and new) and (old-new).Magnitude>.05
                                    log("CHEF ROTATE R UP | delivered="..tostring(ok)
                                        .." | observable ghost turn="..tostring(changed))
                                end
                            elseif down then
                                log("CHEF ROTATE R | no active chef ghost; saved remote rotation already encoded by recording")
                            end
                        elseif (MOBILE_449 and (key=="One" or key=="Two" or key=="Three"))
                            or (sessionPlaceCode and (key=="One" or key=="Two" or key=="Three" or key=="R")) then
                            if down then log("MOBILE: skipped recorded keyboard preview key "..key) end
                        else
                            -- Before first calibration only: replicate the real hotbar
                            -- selection exactly as it was recorded.
                            local okKey,method=sendKey(key,down)
                            if not okKey then error("KEY "..tostring(key).." failed: "..tostring(method)) end
                            if down then keysHeld[key]=true else keysHeld[key]=nil end
                            if down then
                                local unit=({One="pumpkin_farmer",Two="chef_tv_man",Three="medic_cameraman"})[key]
                                if unit then
                                    -- Same key while preview active toggles it OFF.
                                    if selectedPreview==unit then selectedPreview=nil
                                    else selectedPreview=unit end
                                    rotationsSinceSelection=0
                                end
                            end
                            if key=="R" and down and selectedPreview then
                                rotationsSinceSelection=rotationsSinceSelection+1
                            end
                            keyEventCount=keyEventCount+1
                            log(string.format("KEY %s %s @ %.3fs | %s",down and "DOWN" or "UP",key,t,tostring(method)))
                            if keyInfoLabel then
                                keyInfoLabel.Text=string.format("KEY %s %s | avatar STILL\n%d events | %s",down and "DOWN" or "UP",key,keyEventCount,keyboardMode)
                            end
                        end
                    elseif typ=="m" then
                        -- Restore ONLY the recorded Auto Skip click at t=0.811s.
                        -- All other raw mouse clicks must stay disabled to avoid
                        -- double placements and unintended menu closures.
                        if not autoSkipHandled and t>=.75 and t<=1.05
                            and ev[5]==0 and ev[6]==1
                            and math.abs(ev[3]-1036)<30 and math.abs(ev[4]-88)<25 then
                            autoSkipHandled=true
                            local enabled,why=ensureAutoSkipGreen(ev[3],ev[4])
                            if not enabled then
                                log("WARNING: Auto Skip not verified GREEN: "..tostring(why))
                                task.spawn(function()
                                    -- v14 HUD retry, no blind toggles or duplicate concurrent clicks.
                                    task.wait(2.4)
                                    if stopped then return end
                                    local _,_,state=locateAutoSkip()
                                    if state=="RED" then
                                        log("AUTO SKIP RECHECK v14 | indicator still RED; retrying after GUI settled")
                                        local fixed,reason=ensureAutoSkipGreen(ev[3],ev[4])
                                        log("AUTO SKIP RECHECK v14 | "..tostring(fixed)
                                            .." | "..tostring(reason))
                                    elseif state=="GREEN" then
                                        log("AUTO SKIP RECHECK v14 | confirmed GREEN")
                                    else
                                        log("AUTO SKIP RECHECK v14 | unknown state, no blind toggle")
                                    end
                                end)
                            end
                        else
                            skippedRecordedMouse=skippedRecordedMouse+1
                        end

                    elseif typ=="p" then
                        local id=ev[3]
                        local since=os.clock()
                        local held=suspendHeldKeys()
                        local did,why=doPlacement(id,t)
                        paused=paused+os.clock()-since
                        cameraFrozen=nil
                        cameraOverride=nil
                        resumeHeldKeys(held)
                        if did then
                            confirmedPlacementCount=confirmedPlacementCount+1
                        else
                            local message=tostring(why)
                            -- Initial types must calibrate; if they fail there is
                            -- no trustworthy network profile for subsequent placements.
                            -- Also hard-stop on WRONG UNIT / multiple fresh troops.
                            local fatal=(id<=7 or stopped or userStopped
                                or message:find("WRONG UNIT",1,true)
                                or message:find("UNSAFE",1,true)
                                or message:find("WRONG POSITION",1,true))
                            if fatal then
                                error("PLACE #"..tostring(id).." FAILED: "..message)
                            end
                            failedPlacements[id]=message
                            disabledUpgradeIds[id]=true
                            skippedPlacementCount=skippedPlacementCount+1
                            replaySkippedPlaces=skippedPlacementCount
                            say("PLACE #"..id.." UNAVAILABLE; CONTINUE",
                                message.." | later upgrades for this id disabled")
                        end
                    elseif typ=="u" then
                        local id=ev[3]
                        if failedPlacements[id] or disabledUpgradeIds[id] then
                            skippedUpgradeCount=skippedUpgradeCount+1
                            replaySkippedUpgrades=skippedUpgradeCount
                            log("UPGRADE SKIPPED #"..id
                                .." | target missing or prior upgrade could not be verified")
                        else
                            local since=os.clock()
                            local held=suspendHeldKeys()
                            bindCamera()
                            freeze(t)
                            local good,why=guardedUpgrade(id,ev[4],ev[5],t)
                            unbindCamera()
                            paused=paused+os.clock()-since
                            cameraFrozen=nil
                            cameraOverride=nil
                            resumeHeldKeys(held)
                            if good then
                                confirmedUpgradeCount=confirmedUpgradeCount+1
                            else
                                local message=tostring(why)
                                if stopped or userStopped or message:find("WRONG COPY",1,true) then
                                    error("UPGRADE #"..tostring(id).." FAILED: "..message)
                                end
                                disabledUpgradeIds[id]=true
                                skippedUpgradeCount=skippedUpgradeCount+1
                                replaySkippedUpgrades=skippedUpgradeCount
                                say("UPGRADE #"..id.." UNAVAILABLE; CONTINUE",
                                    message.." | future upgrades for this id disabled")
                            end
                        end
                    end
                    if i%25==0 then
                        status.Text=string.format("PLAYING %d/%d | %.0fs / %.0fs",i,#data.actions,t,data.duration)
                        details.Text="Verified placed: "..tostring(confirmedPlacementCount)
                            .." | SKIPPED places: "..tostring(skippedPlacementCount)
                            .." | SKIPPED upgrades: "..tostring(skippedUpgradeCount)
                    end
                end
                log(string.format("REPLAY V27 SUMMARY | confirmed places=%d upgrades=%d | skipped places=%d upgrades=%d | recorded actions=%d",
                    confirmedPlacementCount,confirmedUpgradeCount,
                    skippedPlacementCount,skippedUpgradeCount,#data.actions))
                if skippedPlacementCount>0 or skippedUpgradeCount>0 then
                    say("REPLAY PARTIAL", "Not every placement/upgrade succeeded; skipped units were NEVER marked upgraded")
                end
            end)
            stopped=true
            running=false
            updateMouseShield()
            for k,_ in pairs(keysHeld) do pcall(function() sendKey(k,false) end) end
            keysHeld={}
            cameraFrozen=nil
            cameraOverride=nil
            unbindCamera()
            log("SKIPPED "..skippedMovement.." avatar movement events and "..skippedRecordedMouse.." raw mouse events")
            if victoryStopRequested then
                -- Leave big menu hidden on result screen: it could intercept
                -- the game's green Play Again button.
                collapseReplayMenu(true)
                if compactStatus then compactStatus.Text="AFK • RESULT" end
                say("MATCH ENDED", "Replay stopped on victory/defeat; ready to press Play Again")
            elseif successful then
                collapseReplayMenu(false)
                if replaySkippedPlaces>0 or replaySkippedUpgrades>0 then
                    -- pcall success means NO LUA ERROR, not a full run.
                    say("REPLAY INCOMPLETE",
                        "FAILED: missing "..replaySkippedPlaces.." placements, "
                        ..replaySkippedUpgrades.." upgrades. NOT a successful recording")
                    if compactStatus then compactStatus.Text="AFK • INCOMPLETE" end
                else
                    say("REPLAY COMPLETE","All recorded placement/upgrade actions confirmed")
                end
            else
                collapseReplayMenu(false)
                say("HALTED SAFELY",tostring(reason))
            end
        end)
    end
