-- ---------------------------------------------------------------------------
-- PLAY AGAIN v0.8.8
-- In this game's result GUI the green Play Again graphic may have a TextLabel
-- nested under a non-button Frame.  The old code searched ONLY GuiButtons,
-- reporting a visible victory but failing to find its click target.
-- Detect the real result using visible text, then click the *label* center if
-- there is no clickable GuiButton ancestor.  Never mistake the old Wave 1 HUD
-- under the result overlay for a fresh match.
-- ---------------------------------------------------------------------------
local function screenVisible(n)
    if not n or not n:IsA("GuiObject") or not vis(n) then return false end
    local size=n.AbsoluteSize
    if size.X<3 or size.Y<3 then return false end
    local pos=n.AbsolutePosition
    local cam=workspace.CurrentCamera
    local vp=cam and cam.ViewportSize or Vector2.new(1920,1080)
    return pos.X<vp.X and pos.X+size.X>0 and pos.Y<vp.Y and pos.Y+size.Y>0
end

local function centerInScreen(n)
    local p=midpoint(n)
    local cam=workspace.CurrentCamera
    local vp=cam and cam.ViewportSize or Vector2.new(1920,1080)
    return p.X>=vp.X*.08 and p.X<=vp.X*.92 and p.Y>=vp.Y*.08 and p.Y<=vp.Y*.86
end

local function playAgainEventButton(node)
    if not node then return nil end
    if node:IsA("GuiButton") then return node end
    local p=node.Parent
    while p and p~=pg do
        if p:IsA("GuiButton") and screenVisible(p) then return p end
        if p:IsA("ScreenGui") then break end
        p=p.Parent
    end
    -- A frame's children may contain an ImageButton overlay with a TextLabel
    -- next to it rather than nested inside it.  Choose an overlapping button.
    local parent=node.Parent
    if parent then
        local pos=midpoint(node)
        for _,sibling in ipairs(parent:GetDescendants()) do
            if sibling:IsA("GuiButton") and screenVisible(sibling) then
                local q=sibling.AbsolutePosition
                local size=sibling.AbsoluteSize
                if pos.X>=q.X and pos.X<=q.X+size.X
                    and pos.Y>=q.Y and pos.Y<=q.Y+size.Y then
                    return sibling
                end
            end
        end
    end
    return nil
end

local function resultFallbackXY()
    -- Grounded in the user's 1648x928 victory screenshot: the green button's
    -- center is near (1107, 656).  Scale proportionally for other resolutions.
    local camera=workspace.CurrentCamera
    local vp=camera and camera.ViewportSize or Vector2.new(1648,928)
    return math.floor(vp.X*.6717+.5),math.floor(vp.Y*.708+.5)
end
local function guiButtonOverPoint(x,y)
    local result=nil
    local best=math.huge
    for _,n in ipairs(pg:GetDescendants()) do
        if n:IsA("GuiButton") and screenVisible(n)
            and (not gui or not n:IsDescendantOf(gui))
            and (not mouseShieldGui or not n:IsDescendantOf(mouseShieldGui)) then
            local p,sz=n.AbsolutePosition,n.AbsoluteSize
            if x>=p.X and x<=p.X+sz.X and y>=p.Y and y<=p.Y+sz.Y
                and sz.X>=45 and sz.Y>=20 and sz.X<=430 and sz.Y<=180 then
                local area=sz.X*sz.Y
                if area<best then result,best=n,area end
            end
        end
    end
    return result
end
local function exactResultPlayAgainButton()
    local match=pg:FindFirstChild("Match")
    local finish=match and match:FindFirstChild("MatchFinish")
    local frame=finish and finish:FindFirstChild("MatchFinishFrame")
    local options=frame and frame:FindFirstChild("EndOptions")
    local play=options and options:FindFirstChild("PlayAgain")
    local buttonFrame=play and play:FindFirstChild("ButtonFrame")
    local button=buttonFrame and buttonFrame:FindFirstChild("PlayAgainButton")
    if button and button:IsA("GuiButton") and screenVisible(button) then
        return button
    end
    return nil
end
local function findVictoryPlayAgain()
    local title=nil
    local lostTitle=nil
    local lostMatch=false
    local lostPanel=false
    local lobby=nil
    local playNode=nil
    local playScore=-math.huge
    local candidates={}
    local wonMatch=false
    local totalReward=false
    local crateReward=false
    local winPanel=false
    local wave50=false
    local completed=false
    for _,n in ipairs(pg:GetDescendants()) do
        if n:IsA("GuiObject") and screenVisible(n)
          and (not gui or not n:IsDescendantOf(gui))
          and (not mouseShieldGui or not n:IsDescendantOf(mouseShieldGui)) then
            local label=norm(txt(n))
            local name=norm(n.Name)
            local central=centerInScreen(n)
            if (label=="youwon" or label=="victory" or label:find("youwon",1,true))
               and central then title=n end
            -- Most defeat variants use TextLabels; the title need not be a GuiButton.
            if central and (label=="youlost" or label=="youlose" or label=="defeat"
                or label=="defeated" or label=="gameover" or label=="matchlost"
                or label=="youfailed" or label=="missionfailed"
                or label:find("youlose",1,true) or label:find("youlost",1,true)) then
                lostTitle=n
            end
            if central and (label=="lostmatch" or label=="matchlost"
                or label=="matchfailed" or label=="youhavebeenoverrun") then
                lostMatch=true
            end
            if central and (name:find("defeat",1,true) or name:find("lossmenu",1,true)
                or name:find("losescreen",1,true) or name:find("lostscreen",1,true))
                and n.AbsoluteSize.X>300 and n.AbsoluteSize.Y>180 then
                lostPanel=true
            end
            if (label=="wonmatch" or label=="wonmatch800") and central then wonMatch=true end
            if label=="total" and central then totalReward=true end
            if label:find("youreceived",1,true) and central then crateReward=true end
            if label=="wave50" then wave50=true end
            if label=="100complete" or label=="100percentcomplete" then completed=true end
            if (name:find("victory",1,true) or name:find("resultscreen",1,true)
                or name:find("winmenu",1,true) or name:find("winscreen",1,true))
                and central and n.AbsoluteSize.X>300 and n.AbsoluteSize.Y>180 then
                winPanel=true
            end
            if label=="lobby" or name=="lobbybutton" then lobby=n end
            local textHit=label:find("playagain",1,true)~=nil
            local nameHit=name:find("playagain",1,true)~=nil
            if textHit or nameHit then
                local score=(textHit and 50 or 15)
                    +(n:IsA("TextLabel") and 12 or 0)
                    +(n:IsA("GuiButton") and 10 or 0)
                    +(central and 20 or -40)
                if score>playScore then playNode,playScore=n,score end
                candidates[#candidates+1]=n.ClassName..":"..n.Name
            end
        end
    end
    -- Result artwork may be ImageLabels without machine-readable button text.
    -- Use multiple independent victory signs, NEVER Wave 50 alone.
    local strongVictory=(title~=nil)
        or (wonMatch and (totalReward or lobby~=nil))
        or (winPanel and (totalReward or lobby~=nil or wonMatch))
        or (crateReward and completed and wave50)
    -- Treat defeat as an actual result, not as endless 'waiting for cash'.
    -- Text matching is limited to CENTRAL, visible GUI.  The fallback button
    -- is ONLY used after a result screen is independently verified.
    local strongDefeat=(lostTitle~=nil)
        or (lostMatch and (lobby~=nil or playNode~=nil))
        or (lostPanel and (lobby~=nil or playNode~=nil))
    local active=strongVictory or strongDefeat
    local resultKind=strongDefeat and "DEFEAT" or "VICTORY"
    -- Prefer the EXACT button from the live game's result UI, not an overlaid
    -- TextLabel or a screenshot-derived coordinate.
    if active then
        local exact=exactResultPlayAgainButton()
        if exact then
            playNode=exact
            candidates[#candidates+1]="EXACT:"..exact:GetFullName()
        end
    end
    if active and not playNode then
        local x,y=resultFallbackXY()
        playNode=guiButtonOverPoint(x,y) or {fallback=true,x=x,y=y}
        if #candidates==0 then candidates[1]="IMAGE FALLBACK "..x..","..y end
    end
    return playNode,active,active,table.concat(candidates,", "),
        title or lostTitle,lobby,resultKind
end

isResultActive=function()
    local _,active,titleSeen=findVictoryPlayAgain()
    -- Even if the green button is still loading, don't launch a strategy on
    -- top of a central You won! title.
    return active or titleSeen
end

-- In the results state replay uses stopped=true: gameplay tapWithMethod()
-- refuses VIM mouse down because delayCheck() returns false on STOP.
-- Use an isolated result-click path with task.wait (never unset stopped).
local function playAgainResultMouseClick(x,y)
    if not VIM then return false,"VirtualInputManager unavailable" end
    beginAutoMouseInput()
    local ok,why=pcall(function()
        VIM:SendMouseMoveEvent(x,y,game)
        task.wait(.10)
        if userStopped or destroyed then error("user STOP") end
        VIM:SendMouseButtonEvent(x,y,0,true,game,0)
        task.wait(.15)
        VIM:SendMouseButtonEvent(x,y,0,false,game,0)
    end)
    if not ok then
        pcall(function() VIM:SendMouseButtonEvent(x,y,0,false,game,0) end)
    end
    endAutoMouseInput()
    return ok,ok and "VIM down/up after match STOP" or tostring(why)
end

-- v20: a touch dispatched by Delta is not evidence of a UI click. On the
-- user's phone real VIM mouse clicks work reliably for tower placement and
-- InspectMenu, whereas the prior Play Again TOUCH did not close the result.
-- Try different routes only after waiting AND verifying the same result is
-- still displayed. Bounded to three attempts per match; never spam a button.
local function playAgainOneClick(target,attempt)
    if destroyed or userStopped or not target then
        return false,"Play Again target unavailable / STOP pressed"
    end
    local fallback=(type(target)=="table" and target.fallback)
    local btn=exactResultPlayAgainButton()
        or (not fallback and playAgainEventButton(target) or nil)
    if not fallback and not screenVisible(btn or target) then
        return false,"Play Again GUI no longer visible"
    end
    local x,y
    if btn or not fallback then
        local mid=midpoint(btn or target)
        x,y=math.floor(mid.X+.5),math.floor(mid.Y+.5)
    else
        x,y=target.x,target.y
    end
    log(string.format("PLAY AGAIN TARGET | attempt=%d | button=%s | at=%d,%d | viewport=%dx%d",
        attempt,btn and btn:GetFullName() or "fallback",x,y,liveViewport().X,liveViewport().Y))
    updateMouseShield()
    if mouseShieldGui then mouseShieldGui.Enabled=false end
    if mouseShieldSurface then mouseShieldSurface.Active=false; mouseShieldSurface.Visible=false end
    -- First and final attempts: VIM. Proven on this Redmi by PLACE #1 and #5.
    if attempt==1 or attempt>=3 then
        local shift=0
        if MOBILE_449 and attempt==1 and btn then
            local available=btn.AbsoluteSize.X
            -- The +39px correction is confirmed for 3D clicks, but GUI
            -- hitboxes differ: only apply it if still inside the button.
            local candidate=math.floor(39*liveViewport().X/921+.5)
            if available>=candidate*2+16 then shift=candidate end
        end
        local clickX=x+shift
        local ok,reason=playAgainResultMouseClick(clickX,y)
        log("PLAY AGAIN VIM #"..attempt.." | sent="..tostring(ok)
            .." | x="..clickX.." dx="..shift.." | "..tostring(reason))
        if ok then return true,"VIM at live button @"..clickX..","..y end
    end
    -- Second attempt: invoke ONE real GUI button handler, not another touch.
    if btn then
        if type(getconnections)=="function" and type(firesignal)=="function" then
            for _,eventName in ipairs({"Activated","MouseButton1Click"}) do
                local signal=btn[eventName]
                local ok,connections=pcall(getconnections,signal)
                if ok and type(connections)=="table" and #connections>0 then
                    local sent,err=pcall(function()
                        if eventName=="Activated" then firesignal(signal,nil,1)
                        else firesignal(signal) end
                    end)
                    if sent then
                        log("PLAY AGAIN GUI #"..attempt.." | "..eventName.." | "..btn:GetFullName())
                        return true,"GUI "..eventName
                    end
                    log("PLAY AGAIN GUI error | "..tostring(err))
                end
            end
        end
        local activated,err=pcall(function() btn:Activate() end)
        if activated then
            log("PLAY AGAIN BUTTON ACTIVATE #"..attempt.." | "..btn:GetFullName())
            return true,"GuiButton:Activate()"
        end
        log("PLAY AGAIN ACTIVATE FAILED | "..tostring(err))
    end
    -- Last fallback for executors without VIM or GUI handler.
    if attempt>=3 then
        local ok,why=pcall(function()
            if not VIM then error("VIM unavailable") end
            VIM:SendTouchEvent(1,0,x,y)
            task.wait(.18)
            VIM:SendTouchEvent(1,2,x,y)
        end)
        log("PLAY AGAIN TOUCH BACKUP | sent="..tostring(ok).." | "..tostring(why))
        if ok then return true,"touch backup (unverified)" end
    end
    return false,"no accepted input route on this attempt"
end

local victoryLatched=false
local playAgainAttempts=0
local victoryAbsent=0
local missingTargetLogged=false
local titleOnlyLogged=false
local playAgainSentAt=nil
local playAgainStuckLogged=false
-- Result detection is independent of recorded elapsed time: a victory OR a
-- defeat can happen while money/awake wait loops are blocked. Stop first,
-- release shield, then attempt Play Again only once per finished match.
task.spawn(function()
    while not destroyed do
        local target,active,titleVisible,candidates,title,lobby,resultKind=findVictoryPlayAgain()
        if active then
            victoryAbsent=0
            resultGoneAt=nil
            local now=os.clock()
            if playAgainAttemptedForMatch and playAgainAttempts>=3 and playAgainSentAt
                and not playAgainStuckLogged and now-playAgainSentAt>7 then
                playAgainStuckLogged=true
                log("PLAY AGAIN UNCONFIRMED | 3 bounded attempts; result remains visible, stopping retries")
            end
            local firstTry=(not victoryLatched and not playAgainAttemptedForMatch)
            local retry=(playAgainAttemptedForMatch and playAgainAttempts<3
                and playAgainSentAt and now-playAgainSentAt>=5.5)
            if (firstTry or retry) and CONFIG.autoPlayAgain and not userStopped then
                if running and not victoryStopRequested then
                    victoryStopRequested=true
                    stopped=true
                    updateMouseShield()
                    log(resultKind.." SCREEN VERIFIED | stopping replay and releasing mouse shield")
                end
                if not running then
                    if target then
                        if firstTry then playAgainAttempts=0 end
                        victoryLatched=true
                        playAgainAttemptedForMatch=true
                        playAgainAttempts=playAgainAttempts+1
                        local attempt=playAgainAttempts
                        if attempt>1 then
                            log("PLAY AGAIN STILL VISIBLE | retry "..attempt.."/3 after confirmed unchanged result")
                        end
                        local sent,method=playAgainOneClick(target,attempt)
                        playAgainSentAt=os.clock() -- retry not before 5.5 s
                        playAgainStuckLogged=false
                        if sent then
                            awaitingResultTransition=true
                            autoArmed=CONFIG.autoStartWaveOne
                            if autoButton then
                                autoButton.Text=autoArmed and "AUTO: ON - QUICK START" or "AUTO: OFF - CLICK TO ARM"
                            end
                            say("PLAY AGAIN TRY "..attempt.."/3",resultKind.." | "..method.." | verifying result closes")
                        else
                            say("PLAY AGAIN INPUT FAILED "..attempt.."/3",method)
                        end
                    elseif not missingTargetLogged then
                        missingTargetLogged=true
                        log(resultKind.." result modal found, but Play Again target absent; GUI: "..tostring(candidates))
                    end
                end
            end
        elseif titleVisible then
            victoryAbsent=0
            resultGoneAt=nil
            if not titleOnlyLogged then
                log("RESULT TITLE found, but results buttons not ready; withholding auto-start")
                titleOnlyLogged=true
            end
        else
            victoryAbsent=victoryAbsent+1
            if awaitingResultTransition and not resultGoneAt then
                resultGoneAt=os.clock()
                log("PLAY AGAIN TRANSITION VERIFIED | result screen closed; watching for fresh Wave 1")
            end
            if victoryAbsent>=4 then
                victoryLatched=false
                missingTargetLogged=false
                titleOnlyLogged=false
            end
        end
        task.wait(.45)
    end
end)

-- No arbitrary Wave 1 triple-check delay. Initial Execute can begin on an
-- already-running match, but never replay over existing troops or results UI.
-- After Play Again, require a genuinely fresh Wave 1 as before.
task.spawn(function()
    local previousOccupied=false
    while not destroyed do
        if autoArmed and not running then
            local resultStillVisible=isResultActive and isResultActive()
            local transitionReady=(not awaitingResultTransition)
                or (resultGoneAt and os.clock()-resultGoneAt>=.30)
            if not resultStillVisible and transitionReady then
                local wave=matchActiveWave()
                local ready=wave and (not awaitingResultTransition or wave==1)
                local occupied=ready and knownUnitAlreadyPresent()
                if ready and not occupied and launchReplay then
                    if wave>1 then
                        log("LATE EXECUTE: active Wave "..wave.."; no units placed yet. Starting now (late starts may lose).")
                    else
                        log("WAVE 1 LIVE | starting without extra confirmation delay")
                    end
                    launchReplay("AUTO ACTIVE WAVE "..tostring(wave))
                elseif occupied and not previousOccupied then
                    log("AUTO WATCH: existing units detected; cannot safely restart the recording")
                end
                previousOccupied=not not occupied
            end
        end
        task.wait(.15)
    end
end)
local controller={}
function controller:Destroy()
    destroyed=true
    userStopped=true
    autoArmed=false
    stopped=true
    running=false
    unbindCamera()
    if focusLostConnection then focusLostConnection:Disconnect(); focusLostConnection=nil end
    if focusGainedConnection then focusGainedConnection:Disconnect(); focusGainedConnection=nil end
    if emergencyStopConnection then emergencyStopConnection:Disconnect(); emergencyStopConnection=nil end
    if mouseShieldCASBound then
        pcall(function() CAS:UnbindAction(mouseShieldMoveAction) end)
        mouseShieldCASBound=false
    end
    if mouseShieldGui then mouseShieldGui:Destroy(); mouseShieldGui=nil end
    if compactGui then compactGui:Destroy(); compactGui=nil end
    if gui then gui:Destroy() end
end
